-- Actualizacion de textos en portugues nativo para tourspt

SET NAMES utf8mb4;


UPDATE `tourspt` SET `contenido` = '<h2>City Tour na Cidade de Cusco</h2>\n\n<p><a href=\"https://pachamamaspirit.com/pt/destinos-no-peru/cusco-umbigo-do-mundo\" target=\"_blank\">Cusco</a> é considerada uma cidade <strong>cosmopolita</strong> pela enorme quantidade de viajantes de todo o mundo que a visitam. É uma cidade que conserva raízes profundas em sua história e cultura <strong>andina</strong>, tornando-a única e especial. Antiga capital do Império Inca, Cusco abriga um patrimônio histórico e cultural inestimável.</p>\n\n<p>Além disso, a cidade possui uma vibrante vida cultural, com <strong>festivais</strong> e celebrações tradicionais ao longo de todo o ano, como o <strong>Inti Raymi</strong> (Festa do Sol) e o animado Carnaval de Cusco. É famosa também por sua gastronomia premiada, que inclui pratos imperdíveis como o ceviche peruano, o lomo saltado e o ají de gallina.</p>\n\n<p>A <strong>Pacha Mama Spirit</strong> oferece um dia dedicado para você conhecer o melhor da cidade imperial de Cusco, com visitas guiadas a lugares emblemáticos como: a monumental fortaleza de <strong>Sacsayhuamán</strong>, a Catedral Maior de Cusco, o lendário templo do <strong>Qoricancha</strong>, entre outros atrativos históricos imperdíveis.</p>\n\n<p><img alt=\"Catedral de Cusco City tour\" src=\"https://pachamamaspirit.com/img/galeria/catedral-del-cusco-historia.webp\" style=\"width:100%\" /></p>', `resumen` = '<h2>Ordem das atividades no City Tour Cusco:</h2>\n\n<ul>\n	<li>Fortaleza cerimonial de Sacsayhuamán</li>\n	<li>Almoço em restaurante selecionado</li>\n	<li>Templo do Sol (Qoricancha)</li>\n	<li>Museu Histórico Regional Inka</li>\n	<li>Catedral Maior de Cusco</li>\n</ul>\n\n<p>A duração aproximada do passeio é de 6 horas.</p>', `detallado` = '<h2>Roteiro Detalhado do City Tour Cusco:</h2>\n\n<p>Este passeio começa nas primeiras horas do dia, entre 8h00 e 10h00, conforme sua preferência e agendamento. Buscamos você diretamente na recepção do seu hotel para iniciar nosso trajeto em transporte turístico privativo rumo à imponente fortaleza de <strong>Sacsayhuamán</strong>. Lá faremos uma visita guiada completa, conhecendo a colossal arquitetura de pedra dos incas e a vista panorâmica sobre todo o vale de Cusco.</p>\n\n<p>Ao término da visita em Sacsayhuamán, iremos desfrutar de um delicioso almoço em restaurante tradicional especialmente selecionado. Após a refeição, continuaremos a pé pelas charmosas ruelas de pedra de Cusco até a <strong>Catedral Maior de Cusco</strong> na Plaza de Armas, onde você conhecerá a impressionante história de sua construção, suas obras de arte da Escola Cusquenha e os segredos coloniais.</p>\n\n<p>Em seguida, visitaremos o sagrado templo do <strong>Qoricancha</strong> (Templo do Sol), onde é fascinante observar como a arquitetura colonial espanhola foi construída diretamente sobre os alicerces incas de pedra perfeitamente talhada. Finalizamos nosso tour com uma visita ao <strong>Museu Inka</strong>, que oferece um panorama aprofundado dos costumes, múmias, tecidos e da cosmovisão andina.</p>\n\n<p>Retorno confortável ao seu hotel em Cusco.</p>\n\n<p><img alt=\"Plaza de Armas Cusco\" src=\"https://pachamamaspirit.com/img/galeria/plaza-de-armas-cusco.jpg\" style=\"width:100%\" /></p>', `incluidos` = '<ul>\n	<li>Transporte turístico privativo com motorista profissional</li>\n	<li>Guia oficial de turismo bilíngue credenciado</li>\n	<li>Bilhete Turístico Geral de Cusco (BTG) e entradas necessárias</li>\n	<li>Snack e água mineral engarrafada</li>\n	<li>Almoço tradicional em restaurante selecionado</li>\n</ul>', `importante` = '<p>O Bilhete Turístico de Cusco (BTG) permite o acesso aos sítios arqueológicos inclusos neste tour e a outros atrativos do vale.</p>\n\n<p>Todos os nossos serviços contam com atendimento privativo e personalizado.</p>' WHERE `id` = 1;

UPDATE `tourspt` SET `contenido` = '<h2>Trilha Inca Clássica de 5 Dias até Machu Picchu</h2>\n\n<p>O tour de 5 dias pela Trilha Inca inclui 4 dias de caminhada por trilhas históricas calçadas em pedra e 1 dia inteiro extra para explorar <strong>Machu Picchu</strong> com a subida opcional à montanha <strong>Huayna Picchu</strong>. Ao longo do percurso, vivenciamos a autêntica cultura andina em um dos trajetos de trekking mais emblemáticos do planeta. O Caminho Inca (<strong>Qhapaq Ñan</strong> no idioma quéchua) é um trecho de cerca de 50 km de caminhos originais incas que ligavam a capital Cusco à cidadela de Machu Picchu. Nada supera a emoção de avistar a Cidade Perdida dos Incas a partir do Portal do Sol (Inti Punku) sob os primeiros raios dourados da manhã!</p>\n\n<p>Fazer a Trilha Inca de 5 dias com a <strong>Pacha Mama Spirit</strong> garante suporte completo: carregadores (porteadores) dedicados, equipe de cozinha profissional, equipamentos de camping modernos e guia de trilha altamente experiente. O ritmo mais calmo deste roteiro permite desfrutar cada sítio arqueológico sem pressa e se aclimatar melhor à altitude.</p>\n\n<p>Junte-se a nós em uma das maiores aventuras ao ar livre da América do Sul!</p>\n\n<p><img alt=\"Trilha Inca para Machu Picchu\" src=\"https://pachamamaspirit.com/img/galeria/visita-machu-picchu.webp\" style=\"width:100%\" /></p>', `resumen` = '<h2>Resumo da Trilha Inca Clássica de 5 Dias:</h2>\n\n<p><strong>Turismo Sustentável:</strong> Na Pacha Mama Spirit, promovemos o turismo responsável e o respeito integral às comunidades e ao meio ambiente, apoiando a conservação do parque nacional e garantindo condições éticas e justas aos nossos carregadores.</p>\n\n<p><strong>Nível de Serviço:</strong> Tudo incluído com transporte privativo, guias certificados, cozinheiro de montanha e equipamentos de primeira linha.</p>\n\n<p><strong>Exigência Física:</strong> Moderada a desafiadora. Requer condicionamento físico adequado para caminhar em altitudes de até 4.200 m.</p>\n\n<p><strong>Idade Mínima:</strong> 12 anos (menores de 18 devem estar acompanhados por responsável).</p>\n\n<p><strong>Hospedagem:</strong> 3 noites em acampamento de montanha estruturado e 1 noite em hotel confortável em Aguas Calientes.</p>\n\n<p><strong>Refeições:</strong> 4 cafés da manhã, 4 almoços, 4 jantares e lanches da tarde preparados na hora com ingredientes frescos.</p>\n\n<p><strong>Transporte:</strong> Van privativa Cusco até o Km 82, trem turístico de volta e ônibus de descida em Machu Picchu.</p>\n\n<h2>Itinerário Resumido:</h2>\n<ul>\n	<li><strong>Dia 01:</strong> Cusco – Km 82 – Llulluchapampa</li>\n	<li><strong>Dia 02:</strong> Llulluchapampa – Passo Warmiwañusqa – Chaquicocha</li>\n	<li><strong>Dia 03:</strong> Chaquicocha – Phuyupatamarca – Wiñay Wayna</li>\n	<li><strong>Dia 04:</strong> Wiñay Wayna – Inti Punku – Machu Picchu – Aguas Calientes</li>\n	<li><strong>Dia 05:</strong> Machu Picchu (visita detalhada) – Retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Dia 01: Cusco – Km 82 – Llulluchapampa</h2>\n<p>Bem cedo pela manhã, buscamos você em seu hotel em Cusco para o traslado privativo até o Km 82 (Piscacucho, 2.350 m.s.n.m.), ponto oficial de controle da Trilha Inca. Após a verificação dos passaportes e a reunião informativa com nosso guia, iniciamos a caminhada às margens do rio Urubamba, avistando os sítios arqueológicos de Willca Racca e o imponente complexo de Llactapata. Seguimos em direção ao vale de Cusichaca, com vistas deslumbrantes do pico nevado Verônica (5.850 m). Almoçamos em Chamana e continuamos subindo pelo charmoso povoado de Wayllabamba até nosso primeiro acampamento em Llulluchapampa (3.850 m.s.n.m.), cercado por vegetação andina e ar puro.</p>\n<ul>\n	<li><strong>Tempo estimado:</strong> 7 a 8 horas</li>\n	<li><strong>Distância:</strong> 17 km</li>\n	<li><strong>Altitude máxima:</strong> 3.850 m</li>\n	<li><strong>Dificuldade:</strong> Moderada a exigente</li>\n</ul>\n\n<h2>Dia 02: Llulluchapampa – Passo da Mulher Morta – Chaquicocha</h2>\n<p>Após um reforçado café da manhã, iniciamos a subida rumo ao ponto culminante da Trilha Inca: o famoso Passo Warmiwañusqa (Passo da Mulher Morta), a 4.200 m de altitude. A vista lá de cima sobre os picos nevados é inesquecível! Em seguida, descemos até o vale de Pacaymayo (3.300 m) para um merecido almoço quente. À tarde, subimos em direção ao sítio arqueológico circular de Runkurakay e cruzamos o segundo passo (3.860 m), apreciando a lagoa Yanacocha e as ruínas de Sayacmarca. Chegamos ao nosso acampamento em Chaquicocha (3.670 m), com céu estrelado espetacular.</p>\n<ul>\n	<li><strong>Tempo estimado:</strong> 7 a 8 horas</li>\n	<li><strong>Distância:</strong> 12 km</li>\n	<li><strong>Altitude máxima:</strong> 4.200 m</li>\n	<li><strong>Dificuldade:</strong> Desafiadora</li>\n</ul>\n\n<h2>Dia 03: Chaquicocha – Phuyupatamarca – Wiñay Wayna</h2>\n<p>Este é considerado por muitos o trecho mais bonito da trilha. Caminhamos por caminhos incas entalhados na rocha, passando por túneis originais e florestas subtropicais repletas de orquídeas e aves exóticas. Cruzamos o passo de Phuyupatamarca (3.670 m), conhecido como a \"Cidade nas Nuvens\", um dos sítios incas mais bem preservados da rota. Após o almoço, iniciamos uma descida em escadarias incas até o sítio de Wiñay Wayna (2.700 m), com suas impressionantes terrazas agrícolas debruçadas sobre o vale. Jantar especial de despedida da equipe de carregadores.</p>\n<ul>\n	<li><strong>Tempo estimado:</strong> 5 a 6 horas</li>\n	<li><strong>Distância:</strong> 10 km</li>\n	<li><strong>Altitude máxima:</strong> 3.670 m</li>\n	<li><strong>Dificuldade:</strong> Moderada</li>\n</ul>\n\n<h2>Dia 04: Wiñay Wayna – Inti Punku – Machu Picchu – Aguas Calientes</h2>\n<p>Acordamos antes do amanhecer para a caminhada final rumo ao Inti Punku (Portal do Sol). De lá, temos a lendária primeira vista panorâmica da cidadela de Machu Picchu despontando entre a névoa matinal. Descemos tranquilamente até o santuário inca para fotos clássicas e seguimos para a charmosa vila de Aguas Calientes, onde você terá uma tarde relaxante com banho quente e pernoite em hotel confortável.</p>\n<ul>\n	<li><strong>Tempo estimado:</strong> 3 horas</li>\n	<li><strong>Distância:</strong> 4 km</li>\n	<li><strong>Altitude máxima:</strong> 2.700 m</li>\n	<li><strong>Dificuldade:</strong> Leve a moderada</li>\n</ul>\n\n<h2>Dia 05: Machu Picchu Completo – Retorno a Cusco</h2>\n<p>Pela manhã, tomamos o ônibus de subida até a entrada de Machu Picchu para o tour guiado completo de 2h30 pelos setores agrícola, residencial e religioso do santuário. Aqueles que reservaram a subida opcional a Huayna Picchu ou Montanha Machu Picchu poderão subir neste momento. À tarde, retornamos de ônibus a Aguas Calientes e embarcamos no trem turístico até Ollantaytambo, de onde nosso traslado privativo levará você com todo o conforto de volta ao seu hotel em Cusco.</p>', `incluidos` = '<ul>\n	<li>Reunião informativa (briefing) prévia em seu hotel em Cusco com o guia responsável</li>\n	<li>Transporte privativo de Cusco até o ponto de início no Km 82</li>\n	<li>Hospedagem: 3 noites em acampamento estruturado e 1 noite em hotel em Aguas Calientes</li>\n	<li>Permissões oficiais da Trilha Inca e ingressos para o santuário de Machu Picchu</li>\n	<li>Alimentação completa durante a trilha: 4 cafés da manhã, 4 almoços, 4 jantares e chás da tarde (opções vegetarianas/veganas sem custo adicional)</li>\n	<li>Guia oficial de turismo bilíngue altamente qualificado e certificado</li>\n	<li>Chef de montanha profissional e equipe de cozinha</li>\n	<li>Equipe de carregadores (porteadores) para barracas, mantimentos e até 5 kg de bagagem pessoal por cliente</li>\n	<li>Barracas duplas espaçosas de 4 estações (Eureka Mountain Pass / Doite Expedition)</li>\n	<li>Colchonete térmico isolante, saco de dormir higienizado, travesseiro e manta</li>\n	<li>Bastões de caminhada inclusos</li>\n	<li>Passagem de ônibus de descida de Machu Picchu para Aguas Calientes</li>\n	<li>Passagem de trem turístico de Aguas Calientes para Ollantaytambo</li>\n	<li>Traslado privativo de Ollantaytambo até o seu hotel em Cusco</li>\n	<li>Kit de primeiros socorros completo com cilindro de oxigênio medicinal</li>\n</ul>', `importante` = '<h2>Orientações Importantes sobre a Trilha Inca:</h2>\n\n<h3>Compromisso com os Carregadores (Porteadores):</h3>\n<p>Na <strong>Pacha Mama Spirit</strong>, garantimos condições dignas e justas aos nossos colaboradores: limite rígido de peso conforme a lei peruana, seguro saúde, alimentação de qualidade e remuneração justa. Fazer sua trilha com uma empresa ética faz toda a diferença!</p>\n\n<h3>Estrutura dos Acampamentos:</h3>\n<p>Nossos acampamentos contam com montagem e desmontagem completa pela equipe, barraca-refeitório com mesas e cadeiras confortáveis, barraca-banheiro ecológica e água morna todas as manhãs e noites para sua higiene pessoal.</p>\n\n<h3>O que levar na mochila:</h3>\n<ul>\n	<li>Passaporte original válido utilizado na reserva</li>\n	<li>Mochila pequena de ataque (20 a 30 litros) para o dia a dia</li>\n	<li>Roupas em camadas (térmicas, corta-vento e impermeáveis)</li>\n	<li>Bota ou tênis de trilha amaciado e meias adequadas</li>\n	<li>Protetor solar, repelente de mosquitos e óculos escuros</li>\n	<li>Lanterna de cabeça com pilhas extras e bateria externa (power bank)</li>\n</ul>' WHERE `id` = 2;

UPDATE `tourspt` SET `contenido` = '<p><strong>Vinicunca</strong>, mundialmente conhecida como a <strong>Montanha de 7 Cores</strong> ou Montanha Arco-Íris, é uma formação natural impressionante localizada na cordilheira Vilcanota dos Andes peruanos, na região de Cusco. O que torna Vinicunca tão espetacular é a sua coloração mineral em faixas que variam do vermelho ao ocre, verde-turquesa e dourado, esculpidas pela erosão e sedimentação ao longo de milhões de anos.</p>\n\n<p>A trilha até o topo é uma das experiências de ecoturismo mais procuradas da América do Sul. Devido à altitude que atinge 5.200 metros, a caminhada exige determinação, mas a recompensa ao alcançar o mirante com a vista panorâmica do imponente pico nevado <strong>Ausangate</strong> ao fundo é absolutamente inesquecível!</p>', `resumen` = '<p>Nosso transporte privativo buscará você em seu hotel em Cusco entre 4h00 e 4h30 da manhã para seguir rumo a Cusipata (cerca de 2 horas de viagem), onde saborearemos um delicioso café da manhã andino. Em seguida, avançamos até o ponto de controle de <strong>Fulawasi</strong>, ponto de partida da trilha.</p>\n\n<p>No mirante da montanha, você terá tempo suficiente para admirar o visual, tirar fotos incríveis e receber as explicações geológicas e históricas do nosso guia credenciado. Após a descida, retornamos a Cusipata para um almoço buffet reconfortante antes de regressar a Cusco.</p>\n\n<ul>\n	<li><strong>Duração da caminhada:</strong> cerca de 1h30 a 2 horas (subida)</li>\n	<li><strong>Nível de esforço:</strong> Exigente (devido à altitude)</li>\n	<li><strong>Altitude máxima:</strong> 5.200 m.s.n.m.</li>\n</ul>', `detallado` = '<h2>Dia 1: Excursão de Dia Inteiro à Montanha de 7 Cores</h2>\n\n<p>Iniciamos este passeio imperdível bem cedo, buscando você confortavelmente em seu hotel em Cusco entre 4h00 e 4h30. Cruzamos as paisagens rurais do sul do vale até o vilarejo de Pitumarca / Cusipata, onde faremos uma parada para um café da manhã quente e reforçado.</p>\n\n<p>Continuamos em nossa van turística até a comunidade de <strong>Fulawasi</strong>, onde preparamos nossos bastões e começamos a subida a pé. O trajeto oferece vistas espetaculares de riachos cristalinos, vales avermelhados e rebanhos de lhamas e alpacas pastando livremente em seu habitat natural. Para quem preferir, há a opção de alugar cavalos conduzidos por moradores locais durante o percurso.</p>\n\n<p>Ao alcançar o mirante principal a 5.200 metros de altitude, você contemplará a Montanha Arco-Íris em toda a sua magnitude, ladeada pelo gigante sagrado Ausangate. Teremos tempo de sobra para contemplação e registros fotográficos memoráveis.</p>\n\n<p>Iniciamos o retorno pelo mesmo caminho até nossa van e seguimos para Cusipata, onde um saboroso almoço buffet nos aguarda. Chegamos de volta a Cusco por volta das 17h00.</p>\n\n<h3>Diferenciais Pacha Mama Spirit:</h3>\n<ul>\n	<li>Excursão com guia profissional fluente em inglês e espanhol</li>\n	<li>Grupos reduzidos e atendimento humanizado</li>\n	<li>Kit de oxigênio de emergência e primeiros socorros durante todo o trajeto</li>\n	<li>Operador 100% local com suporte direto</li>\n</ul>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Reunião prévia de orientação (briefing)</li>\n	<li>Traslados de ida e volta desde seu hotel em Cusco em transporte turístico</li>\n	<li>Guia profissional especializado credenciado</li>\n	<li>Café da manhã buffet em Cusipata</li>\n	<li>Almoço buffet com pratos típicos peruanos</li>\n	<li>Bastões de caminhada para suporte</li>\n	<li>Kit de primeiros socorros e cilindro de oxigênio</li>\n</ul>\n\n<h3>Não inclui:</h3>\n<ul>\n	<li>Ingresso de entrada na comunidade de Vinicunca</li>\n	<li>Aluguel opcional de cavalo</li>\n	<li>Bebidas extras e gorjetas</li>\n</ul>', `importante` = '<h3>Recomendações importantes:</h3>\n<ul>\n	<li>Vestir roupas quentes em camadas (segunda pele térmica, fleece e jaqueta corta-vento)</li>\n	<li>Protetor solar fator alto (mínimo 50+), protetor labial e óculos escuros com filtro UV</li>\n	<li>Gorro, luvas e boné</li>\n	<li>Tênis ou bota de caminhada com boa aderência</li>\n	<li>Capa de chuva ou poncho impermeável (especialmente entre novembro e abril)</li>\n	<li>Água mineral e snacks energéticos (castanhas, chocolates)</li>\n	<li>Dinheiro em espécie (soles peruanos) para despesas locais</li>\n</ul>' WHERE `id` = 3;

UPDATE `tourspt` SET `contenido` = '<p>Venha conhecer uma das caminhadas de um dia mais deslumbrantes dos Andes peruanos: a lendária <strong>Lagoa Humantay</strong> (Laguna Humantay), situada aos pés do imponente nevado Salkantay, na mesma cordilheira sagrada que leva a Machu Picchu.</p>\n\n<p>A Lagoa Humantay fascina viajantes do mundo inteiro por suas águas em tons intensos de verde-esmeralda e turquesa, alimentadas pelo degelo das geleiras que coroam os picos nevados ao redor. Na cosmovisão andina, lagoas de montanha são consideradas sagradas (cochas sagradas), locais de oferendas à <em>Pachamama</em> (Mãe Terra) e aos <em>Apus</em> (espíritos das montanhas protetoras).</p>\n\n<p>A melhor época para visitar a lagoa é entre maio e outubro, durante a estação seca, quando o sol andino brilha intensamente e faz as águas turquesas reluzirem como uma joia natural incrustada entre as geleiras.</p>\n\n<p><img alt=\"Caminhada à Lagoa Humantay\" src=\"https://pachamamaspirit.com/img/galeria/Trek-laguna-humantay.webp\" style=\"width:100%\" /></p>', `resumen` = '<p>Nosso transporte turístico passará em seu hotel entre 4h00 e 5h00 para iniciar a viagem rumo ao vilarejo de <strong>Mollepata</strong>, onde faremos uma parada para um saboroso café da manhã. Em seguida, avançamos em nossa van até <strong>Soraypampa</strong> (3.900 m), ponto de início da subida a pé até a lagoa (4.200 m).</p>\n\n<p>Na margem da lagoa, você poderá relaxar, meditar, fazer fotos inesquecíveis e apreciar a imponência dos nevados Humantay e Salkantay. Após a descida, retornamos a Mollepata para um almoço buffet reconfortante antes de voltar a Cusco, com chegada prevista por volta das 18h30.</p>', `detallado` = '<h2>Roteiro Completo da Excursão à Lagoa Humantay</h2>\n\n<p>A <strong>Lagoa Humantay</strong> é um dos atrativos imperdíveis para quem visita Cusco, combinando aventura, natureza intocada e espiritualidade andina.</p>\n\n<p>Partimos bem cedo de Cusco cruzando os vales de Limatambo até chegar a Mollepata. Lá desfrutaremos de um café da manhã nutritivo para recarregar as energias. Continuamos nossa rota por estrada cênica até a planície de Soraypampa, onde nos preparamos para o trekking.</p>\n\n<p>A subida a pé leva aproximadamente 1h30 a 2 horas em ritmo tranquilo. A trilha é íngreme, mas compensada a cada passo pela vista arrebatadora das montanhas nevadas e da flora andina silvestre. Há opção de aluguel de cavalos na base para facilitar a subida.</p>\n\n<p>Ao alcançar a borda da lagoa a 4.200 metros, o contraste entre o azul-turquesa profundo das águas e a parede branca de gelo do glaciar Humantay deixará você sem fôlego! Nosso guia compartilhará histórias fascinantes sobre a importância do local para os povos quéchuas.</p>\n\n<p>Após contemplar essa maravilha, iniciamos a descida suave até Soraypampa e retornamos de van para o almoço em Mollepata, encerrando o dia com retorno tranquilo ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Orientação prévia sobre o tour (briefing)</li>\n	<li>Transporte turístico privativo de ida e volta (Cusco – Soraypampa – Cusco)</li>\n	<li>Café da manhã e almoço buffet em restaurante de montanha</li>\n	<li>Guia profissional de ecoturismo bilíngue</li>\n	<li>Bastões de caminhada inclusos</li>\n	<li>Kit de primeiros socorros e cilindro de oxigênio de emergência</li>\n</ul>\n\n<h3>Não inclui:</h3>\n<ul>\n	<li>Ingresso de entrada na comunidade de Mollepata</li>\n	<li>Aluguel de cavalos</li>\n	<li>Bebidas engarrafadas adicionais e gorjetas</li>\n</ul>', `importante` = '<h3>Dicas e recomendações:</h3>\n<ul>\n	<li>Exige-se aclimatação prévia de pelo menos 1 a 2 dias em Cusco antes de realizar este passeio.</li>\n	<li>Usar calçados de trekking confortáveis com sola tratorada.</li>\n	<li>Levar casaco quente, corta-vento, gorro e luvas (o vento na lagoa é bastante gelado).</li>\n	<li>Protetor solar e óculos com proteção UV.</li>\n	<li>Levar água mineral e alguns chocolates ou folhas de coca para mastigação.</li>\n</ul>' WHERE `id` = 4;

UPDATE `tourspt` SET `contenido` = '<p><strong>Pacote Cusco e Puno — 7 Dias e 6 Noites:</strong> Um roteiro completo e fascinante pelos maiores tesouros do planalto e dos Andes peruanos. Este pacote conecta a lendária capital do Império Inca, <strong>Cusco</strong>, com a mística cidade de <strong>Puno</strong>, às margens do sagrado <strong>Lago Titicaca</strong>.</p>\n\n<p>Durante a viagem, você conhecerá os sítios arqueológicos mais famosos de Cusco, as maravilhas do <strong>Vale Sagrado dos Incas</strong>, pernoitará na vila de Aguas Calientes para explorar ao máximo <strong>Machu Picchu</strong>, e cruzará a famosa <strong>Rota do Sol</strong> através da cordilheira até Puno, navegando nas históricas ilhas flutuantes dos povos Uros e na ilha de Taquile.</p>', `resumen` = '<h2>Resumo do Pacote Cusco e Puno (7 Dias):</h2>\n<ul>\n	<li><strong>Dia 01:</strong> Boas-vindas em Cusco e City Tour Arqueológico</li>\n	<li><strong>Dia 02:</strong> Cusco – Vale Sagrado dos Incas – Conexão de trem a Aguas Calientes</li>\n	<li><strong>Dia 03:</strong> Aguas Calientes – Machu Picchu Completo – Retorno a Cusco</li>\n	<li><strong>Dia 04:</strong> Rota do Sol: Cusco a Puno com paradas cênicas e almoço buffet</li>\n	<li><strong>Dia 05:</strong> Puno – Lago Titicaca: Ilhas Flutuantes dos Uros e Ilha Taquile</li>\n	<li><strong>Dia 06:</strong> Retorno de Puno para Cusco em ônibus executivo</li>\n	<li><strong>Dia 07:</strong> Traslado do hotel ao aeroporto de Cusco</li>\n</ul>', `detallado` = '<h2>Dia 01: Recepção em Cusco e City Tour Arqueológico</h2>\n<p>Recepção acolhedora no aeroporto de Cusco e traslado privativo ao seu hotel selecionado. Tempo para descanso e aclimatação à altitude (3.399 m). Às 13h30, iniciamos o City Tour Arqueológico visitando o Templo do Sol (Qoricancha) e os impressionantes complexos incas de Sacsayhuamán, Qenqo, Puka Pukara e Tambomachay. Noite livre para explorar os charmosos restaurantes da Plaza de Armas.</p>\n\n<h2>Dia 02: Cusco – Vale Sagrado dos Incas – Aguas Calientes</h2>\n<p>Café da manhã no hotel. Saímos em direção ao Vale Sagrado, visitando o mirante de Taray e o sítio arqueológico de Pisac com seu famoso mercado de artesanato. Almoço buffet com culinária regional andina em Urubamba. À tarde, exploramos a fortaleza viva de Ollantaytambo e embarcamos no trem turístico até Aguas Calientes (Machu Picchu Pueblo), onde nossa equipe recepcionará você no hotel.</p>\n\n<h2>Dia 03: Machu Picchu — A Maravilha do Mundo Moderno</h2>\n<p>Bem cedo, tomamos o ônibus até a entrada de Machu Picchu. Visita guiada completa de cerca de 2h30 conhecendo os terraços, praças, templos e a grandiosa engenharia inca. Tempo livre para fotos inesquecíveis. À tarde, retorno de trem a Ollantaytambo e traslado privativo de volta ao seu hotel em Cusco.</p>\n\n<h2>Dia 04: Rota do Sol — De Cusco a Puno</h2>\n<p>Viagem cênica em ônibus turístico de primeira classe cruzando os Andes. Visitas à Capela Sistina das Américas em Andahuaylillas, ao templo monumental de Raqchi (deus Wiracocha), parada fotográfica no ponto mais alto em La Raya (4.335 m) e ao Museu Lítico de Pucará. Almoço buffet incluso em Sicuani. Chegada em Puno no fim da tarde e hospedagem.</p>\n\n<h2>Dia 05: Lago Titicaca — Ilhas Flutuantes de Uros e Ilha Taquile</h2>\n<p>Navegação pelo lago navegável mais alto do mundo (3.812 m). Visita às fascinantes ilhas flutuantes feitas artesanalmente de junco totora pelo povo milenar Uros. Em seguida, navegamos até a ilha de Taquile, mundialmente reconhecida pela UNESCO por suas tradições têxteis andinas. Almoço tradicional com truta fresca do lago e retorno ao hotel em Puno.</p>\n\n<h2>Dia 06: Puno – Retorno a Cusco</h2>\n<p>Café da manhã no hotel. Traslado ao terminal e retorno confortável a Cusco em ônibus executivo, admirando as paisagens do altiplano andino. Chegada em Cusco e traslado ao seu hotel para a última noite livre.</p>\n\n<h2>Dia 07: Cusco – Traslado ao Aeroporto</h2>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Cusco no horário adequado para embarque em seu voo de volta, levando memórias inesquecíveis do Peru!</p>', `incluidos` = '<h3>O que inclui este pacote:</h3>\n<ul>\n	<li>Traslados de chegada e saída em Cusco e Puno (aeroporto/hotel/rodoviária)</li>\n	<li>Transporte turístico para todos os passeios do itinerário</li>\n	<li>Guias profissionais credenciados fluentes em espanhol e inglês</li>\n	<li>Passeios em Cusco: City Tour Arqueológico, Vale Sagrado dos Incas e Machu Picchu</li>\n	<li>Passeios em Puno: Excursão de barco no Lago Titicaca (Uros e Taquile) com almoço</li>\n	<li>Passagem do ônibus turístico Rota do Sol (Cusco a Puno) com almoço buffet e ingressos</li>\n	<li>Passagem de ônibus executivo de retorno (Puno a Cusco)</li>\n	<li>3 noites de hospedagem em Cusco com café da manhã</li>\n	<li>1 noite de hospedagem em Aguas Calientes com café da manhã</li>\n	<li>2 noites de hospedagem em Puno com café da manhã</li>\n	<li>Ingresso oficial para o santuário de Machu Picchu</li>\n	<li>Passagens de trem turístico ida e volta (Ollantaytambo – Aguas Calientes – Ollantaytambo)</li>\n	<li>Passagens de ônibus de subida e descida para Machu Picchu</li>\n</ul>', `importante` = '<h3>Recomendações importantes:</h3>\n<ul>\n	<li>Portar passaporte original válido ou RG brasileiro em excelente estado de conservação (com menos de 10 anos de emissão).</li>\n	<li>Estudantes até 25 anos devem portar a carteira internacional ISIC física válida para usufruir de tarifas especiais quando aplicável.</li>\n	<li>Protetor solar, repelente de insetos (para Machu Picchu) e óculos escuros.</li>\n	<li>Roupas em camadas: casacos para o frio do altiplano em Puno e noites em Cusco, e roupas mais leves para o dia em Machu Picchu.</li>\n</ul>' WHERE `id` = 5;

UPDATE `tourspt` SET `contenido` = '<p><strong>Pacote Lima, Cusco e Puno — 9 Dias e 8 Noites:</strong> O roteiro dos sonhos para quem quer vivenciar o Peru em sua máxima expressão cultural, histórica e gastronômica.</p>\n\n<p>Iniciamos na capital gastronômica da América do Sul, <strong>Lima</strong>, conhecendo seu charmoso centro colonial, a Huaca Pucllana e os modernos bairros litorâneos de Miraflores e San Isidro. Em seguida, voamos para a mágica cidade imperial de <strong>Cusco</strong>, visitando seus sítios arqueológicos, o encantador <strong>Vale Sagrado dos Incas</strong> e a grandiosa cidadela de <strong>Machu Picchu</strong>. Finalizamos navegando nas águas sagradas do <strong>Lago Titicaca</strong> em Puno, descobrindo o modo de vida ancestral das ilhas flutuantes de Uros e Taquile.</p>', `resumen` = '<h2>Resumo do Pacote Lima, Cusco e Puno (9 Dias):</h2>\n<ul>\n	<li><strong>Dia 01:</strong> Recepção e boas-vindas na capital Lima</li>\n	<li><strong>Dia 02:</strong> Lima — City Tour pela Lima Colonial e Moderna</li>\n	<li><strong>Dia 03:</strong> Voo de Lima a Cusco e City Tour Arqueológico</li>\n	<li><strong>Dia 04:</strong> Cusco – Vale Sagrado dos Incas – Conexão de trem a Aguas Calientes</li>\n	<li><strong>Dia 05:</strong> Machu Picchu Maravilha do Mundo – Retorno a Cusco</li>\n	<li><strong>Dia 06:</strong> Rota do Sol: Cusco a Puno com paradas guiadas e almoço buffet</li>\n	<li><strong>Dia 07:</strong> Puno – Navegação no Lago Titicaca (Ilhas Uros e Taquile)</li>\n	<li><strong>Dia 08:</strong> Puno a Juliaca com visita às Chullpas de Sillustani – Retorno a Lima</li>\n	<li><strong>Dia 09:</strong> Lima – Traslado ao Aeroporto Internacional Jorge Chávez</li>\n</ul>', `detallado` = '<h2>Dia 01: Recepção no Aeroporto de Lima</h2>\n<p>Recepção exclusiva no Aeroporto Internacional Jorge Chávez em Lima e traslado privativo ao hotel no tradicional bairro de Miraflores. Tarde livre para passear pelo calçadão do Malecón, conhecer o Shopping Larcomar e saborear a mundialmente famosa gastronomia peruana.</p>\n\n<h2>Dia 02: City Tour pela Lima Colonial e Moderna</h2>\n<p>Pela manhã, realizamos um tour guiado panorâmico pelo sítio pré-inca de Huaca Pucllana. No Centro Histórico, tombado pela UNESCO, visitamos a Plaza Mayor, o Palácio de Governo, a Catedral de Lima e o Convento de São Francisco com suas famosas catacumbas subterrâneas. Tarde livre.</p>\n\n<h2>Dia 03: Voo Lima – Cusco e City Tour Arqueológico</h2>\n<p>Traslado ao aeroporto e voo com destino a Cusco. Na chegada, traslado ao hotel e breve descanso com chá de coca para aclimatação. À tarde, realizamos o City Tour Arqueológico por Qoricancha, Sacsayhuamán, Qenqo, Puka Pukara e Tambomachay.</p>\n\n<h2>Dia 04: Cusco – Vale Sagrado dos Incas – Aguas Calientes</h2>\n<p>Excursão pelo deslumbrante Vale Sagrado dos Incas: visitamos o centro arqueológico de Pisac e sua tradicional feira de artesanato, almoçamos em Urubamba com o melhor da culinária andina, e exploramos a imponente fortaleza inca de Ollantaytambo. No final da tarde, embarcamos no trem turístico até Aguas Calientes, aos pés de Machu Picchu.</p>\n\n<h2>Dia 05: Machu Picchu Maravilha do Mundo – Cusco</h2>\n<p>Subida em ônibus até o santuário de Machu Picchu. Tour guiado de 2h30 descobrindo templos sagrados, relógios solares e praças cerimoniais. Tempo livre para contemplar a vista icônica. À tarde, trem de volta a Ollantaytambo e traslado privativo a Cusco.</p>\n\n<h2>Dia 06: Rota do Sol: De Cusco até Puno</h2>\n<p>Viagem em ônibus panorâmico turístico cruzando a cordilheira. Paradas com visitas guiadas em Andahuaylillas, no Templo de Wiracocha em Raqchi, almoço buffet em Sicuani, no passo montanhoso de La Raya (4.335 m) e no Museu de Pucará. Chegada a Puno ao pôr do sol e pernoite.</p>\n\n<h2>Dia 07: Lago Titicaca — Ilhas Flutuantes de Uros e Taquile</h2>\n<p>Embarque em lancha rápida para navegar pelo Lago Titicaca. Conhecemos a técnica ancestral de construção das ilhas flutuantes de totora dos Uros e seguimos para a Ilha de Taquile, famosa pelas tradições têxteis preservadas. Almoço com truta fresca do lago e retorno ao hotel em Puno.</p>\n\n<h2>Dia 08: Puno – Sítio Arqueológico de Sillustani – Voo a Lima</h2>\n<p>Pela manhã, visitamos as misteriosas torres funerárias pré-incas de Sillustani, às margens da bela lagoa Umayo. Traslado ao aeroporto de Juliaca e embarque em voo de retorno a Lima. Traslado ao hotel em Lima.</p>\n\n<h2>Dia 09: Lima – Voo Internacional de Retorno</h2>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Lima para conexão com seu voo internacional, finalizando uma viagem dos sonhos pelo Peru!</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Todos os traslados privativos de chegada e saída em Lima, Cusco e Puno</li>\n	<li>Transporte turístico com ar-condicionado em todas as excursões</li>\n	<li>Guias profissionais oficiais bilíngues certificados</li>\n	<li>City Tour em Lima (colonial e moderna) com ingressos</li>\n	<li>City Tour Arqueológico em Cusco com ingressos inclusos</li>\n	<li>Tour completo no Vale Sagrado com almoço buffet regional</li>\n	<li>Ingresso oficial para a cidadela de Machu Picchu</li>\n	<li>Passagens de trem turístico ida e volta (Expedition / Voyager)</li>\n	<li>Ônibus de subida e descida em Machu Picchu</li>\n	<li>Ônibus turístico Rota do Sol (Cusco a Puno) com almoço buffet e entradas</li>\n	<li>Navegação pelo Lago Titicaca com visitas a Uros e Taquile com almoço</li>\n	<li>Excursão às Chullpas de Sillustani com ingressos</li>\n	<li>3 noites de hotel em Lima com café da manhã</li>\n	<li>3 noites de hotel em Cusco com café da manhã</li>\n	<li>1 noite de hotel em Aguas Calientes com café da manhã</li>\n	<li>2 noites de hotel em Puno com café da manhã</li>\n</ul>', `importante` = '<h3>Observações importantes:</h3>\n<ul>\n	<li>Não inclui voos domésticos (Lima – Cusco / Juliaca – Lima), que podem ser cotados e incluídos à parte.</li>\n	<li>Documentação necessária: passaporte válido ou RG brasileiro original em bom estado (menos de 10 anos de expedição).</li>\n	<li>Recomenda-se seguro de viagem internacional com cobertura para atividades em altitude.</li>\n</ul>' WHERE `id` = 6;

UPDATE `tourspt` SET `contenido` = '<p><strong>Pacote Lima, Cusco e Puno no Peru — 11 Dias e 10 Noites:</strong> Uma experiência completa e inesquecível pelo país dos incas, com tempo ideal para vivenciar a fundo a cultura, as paisagens de tirar o fôlego e os sítios arqueológicos mais espetaculares da América do Sul.</p>\n\n<p>Este roteiro de 11 dias combina o charme cosmopolita e a gastronomia de <strong>Lima</strong>, a majestade imperial de <strong>Cusco</strong> com o <strong>Vale Sagrado dos Incas</strong>, a maravilha de <strong>Machu Picchu</strong>, e a imensidão mística do <strong>Lago Titicaca</strong> em Puno, incluindo dias extras para aclimatação relaxada e compras de artesanato andino.</p>', `resumen` = '<h2>Resumo do Roteiro de 11 Dias no Peru:</h2>\n<ul>\n	<li><strong>Dia 01:</strong> Boas-vindas e recepção na capital Lima</li>\n	<li><strong>Dia 02:</strong> City Tour pela Lima Colonial e Moderna</li>\n	<li><strong>Dia 03:</strong> Lima a Cusco – Voo matinal e tarde livre para aclimatação</li>\n	<li><strong>Dia 04:</strong> City Tour Arqueológico em Cusco (Sacsayhuamán e Qoricancha)</li>\n	<li><strong>Dia 05:</strong> Vale Sagrado dos Incas (Pisac, Urubamba e Ollantaytambo) – Trem a Aguas Calientes</li>\n	<li><strong>Dia 06:</strong> Machu Picchu Maravilha do Mundo – Retorno a Cusco</li>\n	<li><strong>Dia 07:</strong> Dia livre em Cusco para passeios opcionais (Vinicunca ou Humantay)</li>\n	<li><strong>Dia 08:</strong> Rota do Sol: Ônibus cênico de Cusco até Puno com paradas guiadas</li>\n	<li><strong>Dia 09:</strong> Lago Titicaca: Ilhas Flutuantes dos Uros e Ilha Taquile</li>\n	<li><strong>Dia 10:</strong> Puno a Juliaca com visita a Sillustani – Voo de retorno a Lima</li>\n	<li><strong>Dia 11:</strong> Lima – Traslado ao aeroporto para voo internacional</li>\n</ul>', `detallado` = '<h2>Dia 01: Recepção em Lima</h2>\n<p>Chegada ao Aeroporto Internacional de Lima. Recepção personalizada pela nossa equipe e traslado privativo ao seu hotel no bairro seguro e elegante de Miraflores. Restante do dia livre para descansar.</p>\n\n<h2>Dia 02: Lima Colonial e Moderna</h2>\n<p>Manhã dedicada a conhecer os encantos de Lima: o Parque do Amor em Miraflores com vista para o Oceano Pacífico, o sítio arqueológico de Huaca Pucllana e o Centro Histórico com a Plaza Mayor, a Catedral e as Catacumbas de São Francisco. Tarde livre para saborear ceviches em restaurantes renomados.</p>\n\n<h2>Dia 03: Lima – Cusco</h2>\n<p>Traslado ao aeroporto e voo com destino a Cusco. Recepção e traslado ao hotel. Dia dedicado a relaxar, tomar chá de folhas de coca e se aclimatar com calma à altitude de 3.400 metros.</p>\n\n<h2>Dia 04: City Tour Arqueológico em Cusco</h2>\n<p>À tarde, tour guiado pelos principais templos da cidade: o lendário Templo do Sol Qoricancha e os quatro sítios arqueológicos nos arredores: a impressionante fortaleza de Sacsayhuamán, o centro cerimonial de Qenqo, Puka Pukara e os banhos sagrados de Tambomachay.</p>\n\n<h2>Dia 05: Vale Sagrado dos Incas – Aguas Calientes</h2>\n<p>Exploramos o fértil Vale Sagrado: o mirante de Taray, o complexo arqueológico e mercado típico de Pisac, seguido de almoço buffet requintado em Urubamba. À tarde, visita à grandiosa fortaleza de Ollantaytambo antes de embarcar no trem turístico rumo a Aguas Calientes.</p>\n\n<h2>Dia 06: Machu Picchu Maravilha do Mundo</h2>\n<p>Subida em ônibus até o santuário sagrado de Machu Picchu. Visita guiada minuciosa descobrindo a história e o enigma da Cidade Perdida dos Incas. À tarde, viagem de trem até Ollantaytambo e traslado privativo de volta ao hotel em Cusco.</p>\n\n<h2>Dia 07: Dia Livre em Cusco</h2>\n<p>Dia livre para explorar os ateliês de arte do bairro de San Blas, fazer compras no Mercado San Pedro ou realizar passeios opcionais de aventura como a Montanha de 7 Cores ou a Lagoa Humantay.</p>\n\n<h2>Dia 08: Rota do Sol — De Cusco a Puno</h2>\n<p>Viagem panorâmica em ônibus turístico de primeira classe com paradas culturais: Andahuaylillas, Raqchi, almoço buffet em Sicuani, o passo de La Raya a 4.335 m e o Museu Lítico de Pucará. Chegada a Puno e acomodação em hotel à beira do Titicaca.</p>\n\n<h2>Dia 09: Lago Titicaca — Uros e Taquile</h2>\n<p>Dia de navegação pelo Lago Titicaca. Encontro com as famílias nativas das ilhas flutuantes dos Uros, aprendendo sobre a vida na totora. Em seguida, visita à Ilha de Taquile com almoço típico comunitário e demonstrações culturais. Retorno a Puno.</p>\n\n<h2>Dia 10: Puno – Chullpas de Sillustani – Retorno a Lima</h2>\n<p>No trajeto até o aeroporto de Juliaca, visitamos o complexo funerário pré-inca de Sillustani, com suas imponentes torres de pedra diante da lagoa Umayo. Voo para Lima e traslado ao hotel.</p>\n\n<h2>Dia 11: Lima – Retorno ao Brasil</h2>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Lima para embarque em seu voo de volta, encerrando uma viagem transformadora pelas terras sagradas do Peru!</p>', `incluidos` = '<h3>O que está incluído:</h3>\n<ul>\n	<li>Todos os traslados privativos aeroporto/hotel/aeroporto em Lima, Cusco e Juliaca</li>\n	<li>Transporte turístico para todos os passeios programados</li>\n	<li>Guias oficiais de turismo credenciados fluentes em português/espanhol/inglês</li>\n	<li>City Tour completo em Lima e City Tour Arqueológico em Cusco</li>\n	<li>Excursão ao Vale Sagrado dos Incas com almoço buffet incluso</li>\n	<li>Ingresso para Machu Picchu e passagens de ônibus subida/descida</li>\n	<li>Passagens de trem turístico ida e volta para Machu Picchu</li>\n	<li>Ônibus turístico Rota do Sol com almoço buffet e ingressos de visitas</li>\n	<li>Excursão náutica pelo Lago Titicaca com almoço em Taquile</li>\n	<li>Visita arqueológica a Sillustani com ingressos</li>\n	<li>4 noites de hotel em Cusco com café da manhã</li>\n	<li>1 noite de hotel em Aguas Calientes com café da manhã</li>\n	<li>2 noites de hotel em Puno com café da manhã</li>\n	<li>3 noites de hotel em Lima com café da manhã</li>\n</ul>', `importante` = '<h3>Dicas e informações úteis:</h3>\n<ul>\n	<li>Não inclui passagens aéreas (internacionais ou domésticas), que podem ser cotadas e adicionadas.</li>\n	<li>Passaporte válido por no mínimo 6 meses ou RG brasileiro emitido há menos de 10 anos.</li>\n	<li>Levar sapatos confortáveis para caminhar, protetor solar, agasalhos para o frio noturno e roupas leves para o dia.</li>\n</ul>' WHERE `id` = 7;

UPDATE `tourspt` SET `contenido` = '<p><strong>Circuito Completo Peru: Lima, Paracas, Nazca, Arequipa, Puno e Cusco — 14 Dias e 13 Noites:</strong> O pacote mais abrangente e apaixonante para conhecer o Peru de ponta a ponta.</p>\n\n<p>Este roteiro épico percorre a costa do Pacífico com a vida marinha das <strong>Ilhas Ballestas em Paracas</strong> e o oásis de <strong>Huacachina</strong> em Ica; sobrevoa as enigmáticas <strong>Linhas de Nazca</strong>; desvenda a Cidade Branca de <strong>Arequipa</strong> e a profundeza do <strong>Cânion do Colca</strong> com o majestoso voo do condor; navega pelas águas sagradas do <strong>Lago Titicaca</strong> em Puno; e culmina na capital inca de <strong>Cusco</strong>, o Vale Sagrado e a apoteose da cidadela de <strong>Machu Picchu</strong>.</p>', `resumen` = '<h2>Resumo do Circuito Completo Peru (14 Dias):</h2>\n<ul>\n	<li><strong>Dia 01:</strong> Chegada a Lima e traslado ao hotel</li>\n	<li><strong>Dia 02:</strong> City Tour pela Lima Colonial e Moderna</li>\n	<li><strong>Dia 03:</strong> Lima – Paracas – Ilhas Ballestas e Oásis de Huacachina</li>\n	<li><strong>Dia 04:</strong> Ica – Nazca: Sobrevoo das Linhas de Nazca – Viagem noturna para Arequipa</li>\n	<li><strong>Dia 05:</strong> Chegada a Arequipa e City Tour pela Cidade Branca</li>\n	<li><strong>Dia 06:</strong> Arequipa – Cânion do Colca (Chivay e banhos termais)</li>\n	<li><strong>Dia 07:</strong> Cruz del Cóndor e viagem panorâmica de Colca até Puno</li>\n	<li><strong>Dia 08:</strong> Puno – Lago Titicaca (Ilhas Flutuantes de Uros e Taquile)</li>\n	<li><strong>Dia 09:</strong> Rota do Sol: Ônibus turístico de Puno a Cusco com visitas e almoço</li>\n	<li><strong>Dia 10:</strong> City Tour Arqueológico em Cusco (Sacsayhuamán e Qoricancha)</li>\n	<li><strong>Dia 11:</strong> Vale Sagrado dos Incas (Pisac e Ollantaytambo) – Trem a Aguas Calientes</li>\n	<li><strong>Dia 12:</strong> Machu Picchu Maravilha do Mundo – Retorno a Cusco</li>\n	<li><strong>Dia 13:</strong> Dia livre em Cusco para passeios opcionais (Vinicunca ou descanso)</li>\n	<li><strong>Dia 14:</strong> Cusco – Traslado ao aeroporto para retorno</li>\n</ul>', `detallado` = '<h2>Dia 01: Boas-vindas em Lima</h2>\n<p>Recepção privativa no Aeroporto Internacional Jorge Chávez e traslado ao seu hotel em Miraflores. Restante do dia livre para desfrutar da gastronomia limenha.</p>\n\n<h2>Dia 02: Lima Colonial e Moderna</h2>\n<p>Visita guiada pelo centro histórico de Lima: Plaza Maior, Palácio do Governo, Catedral e as famosas Catacumbas de São Francisco. À tarde, passagem pelo calçadão de Miraflores e Parque do Amor.</p>\n\n<h2>Dia 03: Lima – Paracas – Ilhas Ballestas – Oásis de Huacachina</h2>\n<p>Saída matinal pela rodovia Pan-americana Sul até Paracas. Passeio de lancha rápida às Ilhas Ballestas para avistar leões-marinhos, pinguins de Humboldt e aves guaneras. À tarde, seguimos para o Oásis de Huacachina em Ica, com passeio de buggy pelas dunas e prática de sandboard. Hospedagem em Ica.</p>\n\n<h2>Dia 04: Sobrevoo das Linhas de Nazca – Arequipa</h2>\n<p>Traslado a Nazca para sobrevoo de monomotor sobre os misteriosos geoglifos pré-incas (o Colibri, o Macaco, a Aranha e o Astronauta). No final do dia, embarque em confortável ônibus leito executivo rumo a Arequipa.</p>\n\n<h2>Dia 05: Arequipa — A Cidade Branca</h2>\n<p>Chegada matinal a Arequipa e traslado ao hotel. À tarde, City Tour conhecendo a arquitetura esculpida em pedra vulcânica branca (sillar), o Mirante de Yanahuara com vista para o vulcão Misti e o histórico Monastério de Santa Catalina.</p>\n\n<h2>Dia 06: Arequipa – Vale do Colca</h2>\n<p>Viagem pelas reservas altoandinas avistando vicunhas e alpacas. Passamos pelo ponto mais alto em Patapampa (4.910 m) e descemos ao vale de Chivay. Tarde relaxante nas piscinas de águas termais de La Calera.</p>\n\n<h2>Dia 07: Mirante Cruz del Cóndor – Viagem a Puno</h2>\n<p>Bem cedo, seguimos até o Mirante Cruz del Cóndor para contemplar o voo imponente da maior ave dos Andes sobre o abismo do cânion. À tarde, viagem cênica em ônibus turístico até a cidade lacustre de Puno.</p>\n\n<h2>Dia 08: Lago Titicaca — Uros e Taquile</h2>\n<p>Navegação pelo Lago Titicaca visitando as famílias nativas que vivem sobre as ilhas de totora dos Uros e a ilha de Taquile, com sua cultura têxtil única tombada pela UNESCO. Almoço com truta e regresso a Puno.</p>\n\n<h2>Dia 09: Rota do Sol: Puno a Cusco</h2>\n<p>Viagem em ônibus de primeira classe com paradas guiadas no Museu de Pucará, La Raya (4.335 m), almoço buffet em Sicuani, templo inca de Raqchi e a igreja barroca de Andahuaylillas. Chegada em Cusco.</p>\n\n<h2>Dia 10: Cusco Imperial e Sítios Arqueológicos</h2>\n<p>City tour à tarde visitando o Templo do Sol (Qoricancha) e as quatro fortalezas incas nos arredores: Sacsayhuamán, Qenqo, Puka Pukara e Tambomachay.</p>\n\n<h2>Dia 11: Vale Sagrado dos Incas – Aguas Calientes</h2>\n<p>Excursão pelo Vale Sagrado visitando Pisac e seu colorido mercado, almoço buffet em Urubamba e visita à fortaleza de Ollantaytambo. Embarque no trem panorâmico para Aguas Calientes.</p>\n\n<h2>Dia 12: Machu Picchu — Cidade Perdida dos Incas</h2>\n<p>Subida em ônibus e tour guiado minucioso de 2h30 pela cidadela sagrada. À tarde, trem turístico de volta a Ollantaytambo e traslado privativo a Cusco.</p>\n\n<h2>Dia 13: Dia Livre em Cusco</h2>\n<p>Dia livre para caminhar pelo bairro artístico de San Blas, fazer compras no Mercado San Pedro ou realizar um passeio opcional à Montanha de 7 Cores.</p>\n\n<h2>Dia 14: Cusco – Retorno ao Brasil</h2>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Cusco no horário do seu voo de volta.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Todos os traslados privativos de chegada e saída em Lima, Arequipa, Puno e Cusco</li>\n	<li>Transporte turístico para todos os passeios do itinerário</li>\n	<li>Guias oficiais credenciados em todos os destinos</li>\n	<li>Passeio de barco às Ilhas Ballestas e tour de buggy com sandboard em Huacachina</li>\n	<li>Sobrevoo oficial das Linhas de Nazca com taxas aeroportuárias</li>\n	<li>Ônibus leito executivo Nazca – Arequipa (ou voo conforme opção escolhida)</li>\n	<li>City tour em Arequipa e excursão de 2 dias ao Cânion do Colca</li>\n	<li>Ônibus turístico Chivay – Puno e Rota do Sol (Puno – Cusco) com almoço</li>\n	<li>Excursão náutica no Lago Titicaca (Uros e Taquile) com almoço</li>\n	<li>City Tour Arqueológico em Cusco e Vale Sagrado com almoço buffet</li>\n	<li>Ingresso para Machu Picchu, trem turístico ida/volta e ônibus de subida/descida</li>\n	<li>13 noites de hotel selecionado com café da manhã</li>\n</ul>', `importante` = '<h3>Informações importantes:</h3>\n<ul>\n	<li>O sobrevoo das Linhas de Nazca está sujeito a condições meteorológicas favoráveis no dia.</li>\n	<li>Passaporte original válido ou RG brasileiro em excelente estado de conservação (com menos de 10 anos de expedição).</li>\n	<li>Inclui ampla variedade climática: roupas de verão para a costa e agasalhos térmicos para as noites frias de Puno e Colca.</li>\n</ul>' WHERE `id` = 8;

UPDATE `tourspt` SET `contenido` = '<h2>Machu Picchu em 2 Dias e 1 Noite</h2>\n<p><strong>Machu Picchu</strong> é a joia mais brilhante do Império Inca e uma das Novas Sete Maravilhas do Mundo Moderno. Este pacote de 2 dias e 1 noite foi especialmente planejado para quem deseja conhecer o santuário com calma, pernoitando na aconchegante vila de <strong>Aguas Calientes (Machu Picchu Pueblo)</strong> aos pés da montanha sagrada.</p>\n\n<p>Dormir em Aguas Calientes permite ingressar em Machu Picchu nas primeiras horas da manhã, antes da chegada dos grandes grupos vindos de Cusco de bate-volta, garantindo fotos perfeitas, ar puro e uma conexão espiritual muito mais intensa e tranquila com o local.</p>', `resumen` = '<h2>Resumo do Roteiro (2 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Estação de trem – Viagem cênica até Aguas Calientes – Tarde livre e pernoite em hotel</li>\n	<li><strong>Dia 2:</strong> Subida a Machu Picchu – Tour guiado completo – Trem de retorno a Ollantaytambo e traslado a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado de 2 Dias em Machu Picchu:</h2>\n\n<h3>Dia 1: Cusco – Vale Sagrado – Aguas Calientes</h3>\n<p>Buscamos você em seu hotel em Cusco para o traslado até a estação ferroviária de Ollantaytambo. Embarcamos em um moderno trem turístico panorâmico que serpenteia o cânion do rio Urubamba até a estação de Aguas Calientes. Recepção no desembarque e acompanhamento até o hotel. Tarde livre para passear pela charmosa vila, visitar os banhos termais locais ou saborear a culinária cusquenha em ótimos restaurantes. Pernoite em hotel selecionado.</p>\n\n<h3>Dia 2: Machu Picchu — A Cidadela Sagrada dos Incas – Retorno a Cusco</h3>\n<p>Após o café da manhã no hotel, embarcamos no ônibus que sobe pela cinematográfica rodovia Hiram Bingham até o portal de Machu Picchu. Realizamos uma visita guiada completa de cerca de 2h30 conhecendo o Templo do Sol, a Praça Sagrada, o Intihuatana, o Templo do Condor e os terraços agrícolas. Tempo livre para contemplação. À tarde, descemos de ônibus para Aguas Calientes, embarcamos no trem até Ollantaytambo e nosso traslado privativo levará você com todo o conforto de volta ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Traslados privativos hotel em Cusco – estação de trem – hotel em Cusco</li>\n	<li>Passagens de trem turístico ida e volta (Inca Rail ou PeruRail)</li>\n	<li>1 noite de hospedagem em hotel em Aguas Calientes com café da manhã</li>\n	<li>Passagens de ônibus de subida e descida entre Aguas Calientes e Machu Picchu</li>\n	<li>Ingresso oficial de entrada para o santuário de Machu Picchu</li>\n	<li>Guia oficial de turismo credenciado bilíngue (português/espanhol/inglês)</li>\n	<li>Suporte e assistência personalizada da equipe Pacha Mama Spirit</li>\n</ul>', `importante` = '<h3>Recomendações importantes:</h3>\n<ul>\n	<li>Obrigatório apresentar o passaporte original físico na entrada de Machu Picchu (o mesmo usado na reserva).</li>\n	<li>A bagagem no trem é restrita a 1 mochila pequena ou mala de mão de até 5 kg por pessoa. O restante da bagagem pesada pode ficar guardado com segurança no depósito do seu hotel em Cusco sem custo.</li>\n	<li>Levar calçado de caminhada confortável, protetor solar, repelente de mosquitos e capa de chuva.</li>\n</ul>' WHERE `id` = 9;

UPDATE `tourspt` SET `contenido` = '<h2>Vale Sagrado dos Incas — Passeio de Dia Inteiro</h2>\n<p>O <strong>Vale Sagrado dos Incas</strong> é um dos vales mais férteis e carregados de história de todo o continente americano. Cortado pelo sagrado rio Urubamba (antigo <em>Vilcanota</em>), o vale estende-se entre Cusco e Machu Picchu, abrigando sítios arqueológicos monumentais, fortalezas de pedra, terraços agrícolas em curvas de nível e pitorescas comunidades quéchuas que preservam tradições milenares.</p>\n\n<p>Neste passeio de dia inteiro com a <strong>Pacha Mama Spirit</strong>, você conhecerá o melhor do vale com todo o conforto, visitas guiadas aprofundadas e um almoço buffet requintado com o melhor da gastronomia andina contemporânea.</p>', `resumen` = '<h2>Ordem das Visitas:</h2>\n<ul>\n	<li>Mirante de Taray (vista panorâmica do Vale Sagrado)</li>\n	<li>Complexo Arqueológico e Feira de Artesanato de Pisac</li>\n	<li>Almoço buffet andino em Urubamba</li>\n	<li>Fortaleza viva de Ollantaytambo</li>\n	<li>Povoado tradicional de Chinchero (arte têxtil e igreja colonial)</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado do Vale Sagrado:</h2>\n\n<p>Iniciamos a excursão por volta das 7h30 com embarque em seu hotel em Cusco. Nossa primeira parada é o mirante de Taray, onde contemplamos a vastidão do rio Urubamba serpenteando entre campos agrícolas de milho gigante e montanhas imponentes.</p>\n\n<p>Chegamos a <strong>Pisac</strong>, onde subimos até seu grandioso complexo arqueológico no topo da montanha, admirando a maior rede de terraços agrícolas incas ainda intactos e antigos cemitérios esculpidos no rochedo. Em seguida, descemos ao tradicional mercado de artesanato de Pisac para conhecer jóias em prata, cerâmicas e tecidos feitos à mão.</p>\n\n<p>Ao meio-dia, seguimos para a cidade de <strong>Urubamba</strong> para desfrutar de um delicioso almoço buffet em restaurante campestre selecionado, com saladas frescas, carnes, opções vegetarianas e sobremesas típicas.</p>\n\n<p>À tarde, visitamos a colossal fortaleza cerimonial de <strong>Ollantaytambo</strong>, construída com imensos blocos de granito rosa para proteger a entrada para a selva e Machu Picchu. O vilarejo é conhecido como a \"cidade inca viva\", pois mantém o traçado urbano original da época pré-hispânica.</p>\n\n<p>No retorno a Cusco, visitamos <strong>Chinchero</strong> para uma demonstração cultural ao vivo com tecelãs quéchuas sobre o processo natural de tingimento e tecelagem da lã de alpaca. Chegada a Cusco por volta das 18h30.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Transporte turístico confortável de ida e volta desde seu hotel em Cusco</li>\n	<li>Guia oficial de turismo credenciado bilíngue</li>\n	<li>Almoço buffet completo com culinária regional em Urubamba</li>\n	<li>Demonstração cultural têxtil ao vivo em Chinchero</li>\n	<li>Suporte e atendimento ao cliente dedicado</li>\n</ul>\n\n<h3>Não inclui:</h3>\n<ul>\n	<li>Bilhete Turístico de Cusco (BTG) para acesso aos sítios arqueológicos</li>\n	<li>Bebidas não inclusas no almoço e gorjetas</li>\n</ul>', `importante` = '<h3>Dicas e recomendações:</h3>\n<ul>\n	<li>Usar calçados confortáveis para caminhada em escadarias de pedra.</li>\n	<li>Levar jaqueta corta-vento, protetor solar, óculos de sol e chapéu.</li>\n	<li>Recomenda-se levar dinheiro em espécie (soles peruanos) para compras nas feiras artesanais.</li>\n	<li>Para passageiros que continuam viagem para Machu Picchu no mesmo dia, é possível desembarcar em Ollantaytambo no final da tarde para tomar o trem.</li>\n</ul>' WHERE `id` = 10;

UPDATE `tourspt` SET `contenido` = '<h2>Caminhada Lares até Machu Picchu — 4 Dias e 3 Noites</h2>\n<p>O <strong>Trek Lares</strong> é a rota de caminhada mais autêntica e cultural dos Andes peruanos. Ao contrário da movimentada Trilha Inca clássica, a rota de Lares leva você por vales remotos e intocados onde os povos quéchuas mantêm intactos seus costumes milenares, idioma nativo, roupas tradicionais tecidas em teares manuais e o pastoreio de rebanhos de lhamas e alpacas.</p>\n\n<p>Além do profundo intercâmbio cultural, a trilha oferece banhos relaxantes nas famosas <strong>águas termais medicinais de Lares</strong>, passos de montanha acima de 4.400 metros com lagoas glaciais de tons azulados, e uma chegada triunfal de trem à cidadela sagrada de <strong>Machu Picchu</strong>.</p>', `resumen` = '<h2>Resumo do Itinerário Lares 4 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Banhos Termais de Lares – Trilha até o acampamento em Huacahuasi</li>\n	<li><strong>Dia 2:</strong> Huacahuasi – Passo Condorpass (4.450 m) – Lagoa Aurora – Acampamento em Patacancha</li>\n	<li><strong>Dia 3:</strong> Patacancha – Vilarejo têxtil de Willoc – Ollantaytambo – Trem a Aguas Calientes</li>\n	<li><strong>Dia 4:</strong> Machu Picchu ao amanhecer – Tour guiado completo – Retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado do Lares Trek (4 Dias):</h2>\n\n<h3>Dia 1: Cusco – Termas de Lares – Huacahuasi</h3>\n<p>Saída bem cedo de Cusco em nossa van privativa cruzando o Vale Sagrado até o vale de Lares. Na chegada, você desfrutará de um relaxante banho nas piscinas termais naturais ricas em minerais. Após um almoço delicioso preparado pelo nosso chef de montanha, iniciamos a caminhada subindo suavemente ao longo de um vale andino até nosso primeiro acampamento na tradicional comunidade quéchua de Huacahuasi (3.750 m).</p>\n\n<h3>Dia 2: Huacahuasi – Passo Ipsaycocha – Patacancha</h3>\n<p>O dia mais desafiador e recompensador. Subimos por trilhas ancestrais avistando crianças andinas com ponchos coloridos e rebanhos de alpacas. Conquistamos o passo montanhoso de Ipsaycocha (4.450 m), com vistas panorâmicas arrebatadoras da geleira Veronica. Descemos passando pela deslumbrante lagoa Ipsaycocha até nosso segundo acampamento no vilarejo de Patacancha.</p>\n\n<h3>Dia 3: Patacancha – Ollantaytambo – Aguas Calientes</h3>\n<p>Descemos a pé visitando o vilarejo de Willoc, conhecido pelos tecidos andinos finíssimos. Chegamos a Ollantaytambo para o almoço e exploramos suas ruelas incas preservadas. No final da tarde, embarcamos no trem turístico até Aguas Calientes, onde passaremos a noite em um hotel confortável com banho quente.</p>\n\n<h3>Dia 4: Machu Picchu — Retorno a Cusco</h3>\n<p>Subida em ônibus até o santuário de Machu Picchu nas primeiras horas do dia. Tour guiado de 2h30 conhecendo a história e os mistérios da cidadela. À tarde, retorno de trem a Ollantaytambo e traslado privativo ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Reunião prévia de orientação (briefing) com o guia em Cusco</li>\n	<li>Transporte privativo do hotel em Cusco até Lares e retornos</li>\n	<li>Ingresso para os banhos termais de Lares</li>\n	<li>Guia de montanha profissional bilíngue credenciado</li>\n	<li>Chef de expedição e equipe de cozinha de montanha</li>\n	<li>Mulas de carga e tropeiros para transporte das barracas, comida e até 7 kg de bagagem pessoal</li>\n	<li>Barracas duplas de alta montanha, colchonete isolante e barraca-refeitório com mesas e cadeiras</li>\n	<li>Todas as refeições durante a caminhada (3 cafés da manhã, 3 almoços, 3 jantares)</li>\n	<li>1 noite de hotel em Aguas Calientes com café da manhã</li>\n	<li>Passagens de trem turístico Ollantaytambo – Aguas Calientes – Ollantaytambo</li>\n	<li>Passagens de ônibus subida e descida em Machu Picchu</li>\n	<li>Ingresso oficial para o santuário de Machu Picchu</li>\n	<li>Kit de primeiros socorros e tubo de oxigênio</li>\n</ul>', `importante` = '<h3>Observações importantes:</h3>\n<ul>\n	<li>Exige nível de condicionamento físico moderado a bom.</li>\n	<li>Recomenda-se aclimatação mínima de 2 dias em Cusco antes de iniciar a caminhada.</li>\n	<li>Saco de dormir de pluma/fibra para temperaturas negativas pode ser alugado conosco caso necessário.</li>\n</ul>' WHERE `id` = 11;

UPDATE `tourspt` SET `contenido` = '<h2>Caminhada Salkantay até Machu Picchu — 5 Dias e 4 Noites</h2>\n<p>O <strong>Salkantay Trek</strong> foi eleito pela revista internacional <em>National Geographic Adventure</em> como uma das 25 melhores trilhas de trekking do planeta. É a alternativa perfeita e mais espetacular à Trilha Inca tradicional, dispensando o limite rígido de vagas daquela rota e proporcionando uma variedade de ecossistemas incomparável.</p>\n\n<p>Ao longo de 5 dias inesquecíveis, você sairá das planícies glaciais aos pés do colossal pico nevado <strong>Salkantay</strong> (6.271 m), cruzará o cênico passo montanhoso a 4.630 metros de altitude e descerá gradualmente até a exuberante floresta tropical nublada (ceja de selva), passando por cafezais, plantações de maracujá e rios cristalinos até chegar triunfante a <strong>Machu Picchu</strong>.</p>', `resumen` = '<h2>Resumo do Roteiro Salkantay 5 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Mollepata – Soraypampa – Lagoa Humantay – Acampamento Soraypampa</li>\n	<li><strong>Dia 2:</strong> Soraypampa – Passo Salkantay (4.630 m) – Huayracmachay – Acampamento Chaullay</li>\n	<li><strong>Dia 3:</strong> Chaullay – Collpapampa – Selva Alta – Visita a cafezais – Acampamento Lucmabamba</li>\n	<li><strong>Dia 4:</strong> Lucmabamba – Trilha Inca de Llactapata (vista de Machu Picchu) – Hidroelétrica – Aguas Calientes</li>\n	<li><strong>Dia 5:</strong> Machu Picchu Maravilha do Mundo – Trem a Ollantaytambo – Retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado do Salkantay Trek:</h2>\n\n<h3>Dia 1: Cusco – Mollepata – Soraypampa – Lagoa Humantay</h3>\n<p>Partida às 5h00 do seu hotel em Cusco rumo a Mollepata para o café da manhã. Seguimos até Challacancha para iniciar a caminhada até Soraypampa (3.900 m), onde almoçamos em nosso acampamento base. À tarde, subimos até a deslumbrante <strong>Lagoa Humantay</strong> (4.200 m) para contemplar suas águas turquesas sob a geleira. Retorno ao acampamento para jantar e descanso.</p>\n\n<h3>Dia 2: Soraypampa – Passo Salkantay (4.630 m) – Chaullay</h3>\n<p>Acordamos cedo com chá de coca na barraca. Iniciamos a subida gradual até o majestoso <strong>Passo Salkantay</strong> (4.630 m), o ponto mais alto de toda a rota. Após celebrar a conquista diante da gigantesca parede de gelo do Apu Salkantay, iniciamos a descida em direção à borda da floresta, almoçando em Huayracmachay e acampando na acolhedora localidade de Chaullay (2.900 m).</p>\n\n<h3>Dia 3: Chaullay – Selva Alta – Lucmabamba</h3>\n<p>Caminhamos através da floresta nublada acompanhando o rio Santa Teresa, apreciando cachoeiras, orquídeas nativas e plantações de café orgânico, abacate e maracujá. Chegamos a Lucmabamba, onde participamos de uma experiência vivencial de colheita e torrefação de café andino com agricultores locais.</p>\n\n<h3>Dia 4: Lucmabamba – Sítio Inca de Llactapata – Aguas Calientes</h3>\n<p>Subimos por um trecho original de caminho inca até o sítio arqueológico de <strong>Llactapata</strong>, de onde se tem uma vista frontal panorâmica e exclusiva de Machu Picchu a partir de outra montanha! Descemos até a estação Hidroelétrica para o almoço e caminhamos cerca de 3 horas ao longo dos trilhos do trem cercados por vegetação exuberante até Aguas Calientes. Pernoite em hotel com banho quente.</p>\n\n<h3>Dia 5: O Grande Dia de Machu Picchu – Cusco</h3>\n<p>Subida em ônibus até Machu Picchu para o tour guiado de cerca de 2h30 descobrindo cada recanto da cidade inca. À tarde, descida a Aguas Calientes, embarque no trem panorâmico até Ollantaytambo e traslado privativo ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui o Salkantay Trek:</h3>\n<ul>\n	<li>Briefing preparatório completo em Cusco no dia anterior</li>\n	<li>Transporte turístico Cusco – Mollepata / Challacancha</li>\n	<li>Guia profissional de trekking bilíngue certificado</li>\n	<li>Chef de montanha experiente e equipe de cozinha</li>\n	<li>Cavalos de carga e arrieiros para levar barracas, alimentos e até 6 kg de pertences de cada passageiro</li>\n	<li>Equipamentos de camping de primeira linha (barracas duplas 4 estações, isolantes térmicos, barraca-refeitório)</li>\n	<li>Todas as refeições durante a trilha (4 cafés da manhã, 4 almoços, 4 jantares)</li>\n	<li>1 noite de hospedagem em hotel em Aguas Calientes com café da manhã</li>\n	<li>Passagem de trem turístico de retorno (Aguas Calientes – Ollantaytambo)</li>\n	<li>Passagens de ônibus de subida e descida em Machu Picchu</li>\n	<li>Ingresso oficial para o santuário de Machu Picchu</li>\n	<li>Traslado privativo Ollantaytambo – Cusco</li>\n	<li>Cilindro de oxigênio e maleta de primeiros socorros</li>\n</ul>', `importante` = '<h3>Recomendações e requisitos:</h3>\n<ul>\n	<li>Exige bom preparo físico e espírito de aventura.</li>\n	<li>Aclimatação prévia obrigatória de pelo menos 2 a 3 dias em Cusco.</li>\n	<li>Trazer roupas térmicas para as duas primeiras noites frias de montanha e roupas leves e frescas para os dias na floresta.</li>\n	<li>Repelente forte de mosquitos (indispensável na floresta e em Aguas Calientes).</li>\n</ul>' WHERE `id` = 12;

UPDATE `tourspt` SET `contenido` = '<h2>Lago Titicaca — Ilhas Flutuantes dos Uros e Taquile (2 Dias e 1 Noite)</h2>\n<p>A 3.812 metros de altitude, o <strong>Lago Titicaca</strong> é o lago navegável mais alto do mundo e o berço místico da civilização andina: segundo a lenda sagrada, de suas águas profundas emergiram <em>Manco Cápac</em> e <em>Mama Ocllo</em> para fundar o poderoso Império Inca.</p>\n\n<p>Nesta experiência cultural autêntica de 2 dias e 1 noite, você conhecerá o povo milenar dos <strong>Uros</strong>, que construiu suas próprias ilhas flutuantes com camadas sobrepostas de junco totora, e pernoitará na pacífica <strong>Ilha Taquile</strong> (ou Amantaní), vivenciando o turismo comunitário com famílias locais sob um céu noturno deslumbrante repleto de constelações andinas.</p>', `resumen` = '<h2>Resumo do Roteiro (2 Dias no Lago Titicaca):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Saída do porto de Puno – Visita às Ilhas Flutuantes dos Uros – Navegação até Taquile – Hospedagem comunitária e jantar com famílias locais</li>\n	<li><strong>Dia 2:</strong> Caminhada pela Ilha Taquile – Demonstração de arte têxtil UNESCO – Almoço tradicional de truta – Retorno ao porto de Puno</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado no Lago Titicaca:</h2>\n\n<h3>Dia 1: Puno – Ilhas Flutuantes de Uros – Ilha Taquile</h3>\n<p>Pela manhã, buscamos você em seu hotel em Puno e seguimos para o cais principal. Embarcamos em lancha turística navegando pelas águas calmas do lago até as singulares <strong>Ilhas Flutuantes dos Uros</strong>. As famílias locais compartilharão como colhem o junco totora para erguer suas casas, ilhas e embarcações tradicionais. Em seguida, navegamos por cerca de 2 horas até a <strong>Ilha Taquile</strong>. Subimos por caminhos de pedra até a comunidade anfitriã, onde seremos recebidos com carinho para o almoço e acomodação em quartos aconchegantes de casas de família nativas. À noite, jantar andino caseiro e observação de estrelas.</p>\n\n<h3>Dia 2: Vivência Cultural em Taquile – Retorno a Puno</h3>\n<p>Após o café da manhã caseiro, caminhamos pela praça principal de Taquile, apreciando a impressionante vista das águas azuis do lago contrastando com os picos nevados da Cordilheira Real boliviana no horizonte. Conheceremos os mestres tecelões da ilha, cuja arte têxtil manual feita exclusivamente por homens foi declarada Patrimônio Cultural Imaterial da Humanidade pela UNESCO. Saboreamos um delicioso almoço com truta grelhada e sopa de quinoa, descemos pelo porto e retornamos de barco a Puno, com chegada prevista às 16h30.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Traslados de ida e volta entre seu hotel em Puno e o porto lacustre</li>\n	<li>Embarcação a motor turística durante os 2 dias de navegação</li>\n	<li>Guia profissional bilíngue oficial credenciado</li>\n	<li>Ingressos de acesso às Ilhas dos Uros e à Ilha de Taquile</li>\n	<li>1 noite de hospedagem em casa de família nativa em Taquile (ou Amantaní)</li>\n	<li>Alimentação completa na ilha: 1 café da manhã, 2 almoços e 1 jantar comunitário</li>\n</ul>', `importante` = '<h3>Recomendações importantes:</h3>\n<ul>\n	<li>As noites no Lago Titicaca são bastante frias: levar agasalho pesado, meias de lã e gorro.</li>\n	<li>Durante o dia a radiação solar na altitude é intensa: levar protetor solar e chapéu.</li>\n	<li>A hospedagem comunitária é simples, limpa e acolhedora, proporcionando uma imersão cultural rica e humana.</li>\n	<li>Levar dinheiro em espécie em soles peruanos para comprar peças de artesanato diretamente dos tecelões locais.</li>\n</ul>' WHERE `id` = 13;

UPDATE `tourspt` SET `contenido` = '<h2>Cânion do Colca e Voo do Condor — 2 Dias e 1 Noite saindo de Arequipa</h2>\n<p>O <strong>Cânion do Colca</strong> (Cañón del Colca), localizado a cerca de 160 km da Cidade Branca de Arequipa, é um dos desfiladeiros mais profundos da Terra, atingindo mais de 3.400 metros de profundidade — mais que o dobro da profundidade do Grand Canyon nos Estados Unidos!</p>\n\n<p>Neste tour inesquecível de 2 dias, você atravessará reservas nacionais repletas de rebanhos de vicunhas, lhamas e alpacas, passará por mirantes de vulcões ativos, relaxará em piscinas termais naturais cercadas de cânions e presenciará um dos espetáculos mais marcantes da natureza: o voo majestoso do <strong>Condor Andino</strong> em seu habitat selvagem.</p>', `resumen` = '<h2>Resumo do Roteiro Colca 2 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Arequipa – Reserva Salinas y Aguada Blanca – Passo dos Vulcões (4.910 m) – Chivay – Banhos termais de La Calera</li>\n	<li><strong>Dia 2:</strong> Chivay – Mirante Cruz del Cóndor (observação dos condores) – Povoados típicos de Pinchollo e Maca – Retorno a Arequipa (ou conexão para Puno)</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado no Cânion do Colca:</h2>\n\n<h3>Dia 1: Arequipa – Pampa Cañahuas – Chivay</h3>\n<p>Saída entre 7h30 e 8h00 do seu hotel em Arequipa. Subimos pelas encostas dos vulcões Misti e Chachani em direção à Reserva Nacional de Pampa Cañahuas, onde avistamos vicunhas silvestres pastando livremente. Paramos em Patawasi para provar o tradicional chá de coca ou muña. Cruzamos o Passo dos Vulcões em Patapampa (4.910 m), o ponto mais elevado da rota com vista para os vulcões Sabancaya, Ampato e Hualca Hualca. Descemos à cidade de Chivay (3.600 m) para um almoço buffet com gastronomia local. À tarde, relaxamos nas deliciosas piscinas de águas termais de La Calera. Jantar folclórico opcional e pernoite em hotel.</p>\n\n<h3>Dia 2: Cruz del Cóndor – Vilarejos do Vale – Arequipa</h3>\n<p>Após café da manhã cedo, partimos pela margem do cânion admirando as milenares terrazas agrícolas incas e pré-incas ainda cultivadas. Chegamos ao espetacular <strong>Mirante Cruz del Cóndor</strong>, onde o cânion se aprofunda vertiginosamente. Ali aguardamos as correntes térmicas ascendentes que elevam os gigantescos condores andinos a poucos metros dos visitantes — um momento mágico! No retorno, visitamos os povoados coloniais de Maca e Yanque com suas igrejas barrocas. Almoço em Chivay e regresso a Arequipa por volta das 17h00 (com opção de seguir viagem para Puno).</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Transporte turístico confortável de ida e volta desde seu hotel em Arequipa</li>\n	<li>Guia oficial de turismo credenciado bilíngue</li>\n	<li>1 noite de hospedagem em hotel em Chivay com café da manhã</li>\n	<li>Visita guiada ao Mirante Cruz del Cóndor e mirantes panorâmicos</li>\n	<li>Paradas nas reservas naturais e no Mirante dos Vulcões</li>\n</ul>\n\n<h3>Não inclui:</h3>\n<ul>\n	<li>Boleto Turístico del Colca (BTC) oficial</li>\n	<li>Entrada para as piscinas de águas termais de La Calera</li>\n	<li>Almoços e jantares em Chivay</li>\n</ul>', `importante` = '<h3>Observações importantes:</h3>\n<ul>\n	<li>O avistamento dos condores ocorre na quase totalidade dos dias, dependendo das condições de vento e temperatura.</li>\n	<li>As manhãs e noites em Chivay e no cânion costumam ser bastante frias: levar agasalhos adequados.</li>\n	<li>Possibilidade de conexão direta em ônibus turístico de Chivay para Puno no Dia 2, otimizando o roteiro para quem segue viagem para o Lago Titicaca.</li>\n</ul>' WHERE `id` = 14;

UPDATE `tourspt` SET `contenido` = '<h2>Trek Choquequirao — 4 Dias e 3 Noites: A Irmã Sagrada de Machu Picchu</h2>\n<p><strong>Choquequirao</strong> (que em quéchua significa \"Berço de Ouro\") é uma das ciudadelas incas mais espetaculares, bem preservadas e misteriosas de todo o Peru. Empoleirada sobre o imenso cânion do rio Apurímac a 3.050 metros de altitude, Choquequirao é acessível <strong>única e exclusivamente a pé</strong>, o que a manteve livre do turismo de massa e preservou uma atmosfera de magia e isolamento que poucos lugares no mundo ainda proporcionam.</p>\n\n<p>Com o dobro do tamanho de Machu Picchu e apenas cerca de 30% escavada até o momento, a cidade impressiona por suas praças cerimoniais, templos, residências dos sacerdotes e os famosos terraços agrícolas adornados com lhamas esculpidas em pedras brancas incrustadas nos paredões.</p>', `resumen` = '<h2>Resumo do Roteiro Choquequirao 4 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Cachora – Mirante Capuliyoc – Descida ao Cânion do Apurímac – Acampamento Chiquisca</li>\n	<li><strong>Dia 2:</strong> Chiquisca – Playa Rosalina – Subida desafiadora até Marampata – Acampamento Choquequirao</li>\n	<li><strong>Dia 3:</strong> Dia inteiro dedicado a explorar a cidadela de Choquequirao – Pôr do sol nos terraços das lhamas</li>\n	<li><strong>Dia 4:</strong> Choquequirao – Descida ao rio – Subida a Capuliyoc – Retorno triunfal a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado da Expedição Choquequirao (4 Dias):</h2>\n\n<h3>Dia 1: Cusco – Cachora – Chiquisca</h3>\n<p>Saímos de Cusco às 5h00 em nossa van privativa em direção ao povoado de San Pedro de Cachora. Encontramos nossa equipe de tropeiros e mulas de carga. Começamos a caminhada subindo até o Mirante de Capuliyoc (2.900 m), onde se descortina a primeira vista espetacular do cânion do Apurímac e dos picos nevados Padreyoc. Iniciamos uma descida cênica em zigue-zague até nosso primeiro acampamento em Chiquisca (1.900 m), em clima agradável e acolhedor.</p>\n\n<h3>Dia 2: Chiquisca – Playa Rosalina – Marampata – Choquequirao</h3>\n<p>Após café da manhã nutritivo, descemos até a Playa Rosalina para cruzar a ponte sobre o impetuoso rio Apurímac (1.500 m). Em seguida, enfrentamos a subida mais íngreme e exigente do percurso até o vilarejo de Marampata (2.850 m), onde almoçamos com vista panorâmica. Caminhamos mais 1h30 em trilha suave até o acampamento oficial aos pés das ruínas de Choquequirao.</p>\n\n<h3>Dia 3: Exploração Completa da Cidadela Perdida de Choquequirao</h3>\n<p>Dedicamos o dia inteiro para desvendar esta maravilha arqueológica na companhia do nosso guia especializado. Visitamos o Setor Principal, a Praça Cerimonial, o Palácio Real, o Usnu (plataforma cerimonial) e descemos até os famosos terraços das Lhamas do Sol, com desenhos de animais em mosaico de pedras brancas. O pôr do sol sobre o cânion é uma experiência quase mística.</p>\n\n<h3>Dia 4: Choquequirao – Capuliyoc – Cusco</h3>\n<p>Iniciamos o caminho de retorno descendo até o rio Apurímac e vencendo a subida final até o mirante de Capuliyoc, onde nosso motorista nos espera com um almoço comemorativo. Retorno privativo a Cusco, com chegada prevista por volta das 18h30.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Briefing prévio com o guia em Cusco</li>\n	<li>Transporte privativo de ida e volta (Cusco – Cachora / Capuliyoc – Cusco)</li>\n	<li>Guia oficial de montanha bilíngue credenciado e especialista em arqueologia andina</li>\n	<li>Chef profissional de expedição e equipe de apoio</li>\n	<li>Mulas de carga e arrieiros para levar todo o equipamento de camping, comida e até 7 kg de bagagem por cliente</li>\n	<li>Barracas duplas 4 estações de alta qualidade, isolantes térmicos e barraca-refeitório</li>\n	<li>Alimentação completa durante a trilha (3 cafés da manhã, 4 almoços, 3 jantares)</li>\n	<li>Ingresso oficial de entrada para o parque arqueológico de Choquequirao</li>\n	<li>Kit de primeiros socorros e oxigênio medicinal</li>\n</ul>', `importante` = '<h3>Requisitos e orientações:</h3>\n<ul>\n	<li>Exige excelente preparo físico: são cerca de 32 km com fortes desníveis positivos e negativos (cerca de 1.500 m de desnível por dia).</li>\n	<li>O clima varia drasticamente: calor intenso e sol forte no fundo do cânion, e noites frias na montanha.</li>\n	<li>Levar calçado de trekking firme e amaciado, protetor solar potente, repelente de mosquitos e bastões de caminhada.</li>\n</ul>' WHERE `id` = 15;

UPDATE `tourspt` SET `contenido` = '<h2>Linhas de Nazca e Oásis de Huacachina — 2 Dias saindo de Lima</h2>\n<p>As <strong>Linhas de Nazca</strong> constituem um dos maiores enigmas da arqueologia mundial. Declaradas Patrimônio Mundial pela UNESCO, esses imensos geoglifos traçados no chão do deserto há mais de dois mil anos retratam animais como o Beija-flor, o Macaco, o Condor e a Aranha, com proporções tão monumentais que só podem ser compreendidos plenamente a partir do ar.</p>\n\n<p>Combinamos este sobrevoo inesquecível com a adrenalina do <strong>Oásis de Huacachina</strong> em Ica, a única lagoa natural cercada de dunas gigantes da América do Sul, onde você vivenciará um eletrizante passeio de buggy (tubulares) e praticará sandboard nas areias do deserto ao pôr do sol.</p>', `resumen` = '<h2>Resumo do Roteiro (2 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Saída de Lima em ônibus turístico executivo até Ica – Check-in no hotel – Tarde de aventura em Huacachina com passeio de buggy 4x4 e sandboard ao pôr do sol</li>\n	<li><strong>Dia 2:</strong> Traslado ao aeródromo de Nazca – Sobrevoo clássico das Linhas de Nazca em monomotor – Almoço e retorno de ônibus executivo a Lima</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<h3>Dia 1: Lima – Ica – Oásis de Huacachina</h3>\n<p>Pela manhã, buscamos você em seu hotel em Lima para embarcar em moderno ônibus turístico pela rodovia Pan-americana Sul rumo a Ica (aproximadamente 4h30 de viagem). Recepção em Ica e traslado ao hotel. À tarde, seguimos para o espetacular Oásis de Huacachina, uma lagoa de águas esmeraldas cercada de palmeiras no meio do deserto. Embarcamos em potentes buggies 4x4 pilotados por motoristas credenciados que sobem e descem as dunas gigantes em uma verdadeira montanha-russa natural, com paradas para praticar sandboard nas encostas de areia e contemplar um pôr do sol dourado inesquecível. Noite em hotel em Ica.</p>\n\n<h3>Dia 2: Sobrevoo das Linhas de Nazca – Retorno a Lima</h3>\n<p>Após o café da manhã, nosso transporte privativo nos levará ao aeródromo Maria Reiche em Nazca. Após as instruções de segurança, embarcamos em uma aeronave monomotor com assento na janela garantido para todos os passageiros. Durante cerca de 35 minutos de voo, o piloto realizará manobras suaves em ambos os lados para você avistar e fotografar com perfeição as figuras icônicas: o Beija-flor, a Espiral, o Macaco, o Pelicano, as Mãos e o misterioso Astronauta. Após o sobrevoo e tempo para almoço em Nazca, embarcamos no ônibus executivo de retorno a Lima, com chegada prevista à noite.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Passagens de ônibus executivo de primeira classe Lima – Ica e Nazca/Ica – Lima (Cruz del Sur ou similar)</li>\n	<li>Todos os traslados privativos locais entre rodoviária, hotéis e aeródromos</li>\n	<li>1 noite de hospedagem em hotel em Ica com café da manhã</li>\n	<li>Passeio de buggy 4x4 e pranchas de sandboard em Huacachina</li>\n	<li>Sobrevoo oficial de 35 minutos sobre as Linhas de Nazca em avião monomotor</li>\n	<li>Guia e assistência local permanente</li>\n</ul>\n\n<h3>Não inclui:</h3>\n<ul>\n	<li>Taxa de embarque do aeródromo de Nazca (TUUA) e ingresso do Ministério da Cultura</li>\n	<li>Almoços e jantares</li>\n</ul>', `importante` = '<h3>Recomendações importantes:</h3>\n<ul>\n	<li>Obrigatório apresentar o passaporte original físico (ou RG) para o embarque no voo de Nazca.</li>\n	<li>Pessoas propensas a enjoos devem tomar medicamento preventivo 30 minutos antes do sobrevoo e evitar refeições pesadas antes de voar.</li>\n	<li>Levar roupas leves de verão, óculos escuros, boné e protetor solar com alto fator de proteção.</li>\n</ul>' WHERE `id` = 16;

UPDATE `tourspt` SET `contenido` = '<h2>Reserva Nacional Tambopata — Amazônia Peruana (3 Dias e 2 Noites)</h2>\n<p>A <strong>Reserva Nacional Tambopata</strong>, localizada na bacia amazônica do sudeste do Peru a partir de Puerto Maldonado, é uma das regiões com maior biodiversidade e riqueza biológica de todo o planeta Terra. Lar de onças-pintadas, antas, ariranhas gigantes, centenas de espécies de aves e primatas, a reserva oferece uma imersão mágica na floresta primária intacta.</p>\n\n<p>Hospedado em um ecolodge charmoso e sustentável construído em madeira nativa na margem do rio Madre de Dios, você fará caminhadas guiadas por naturalistas, navegará em canoas pelo espelho d\'água do <strong>Lago Sandoval</strong> e contemplará o colorido estrondoso da <strong>colpa de araras e papagaios</strong> ao amanhecer.</p>', `resumen` = '<h2>Resumo do Roteiro Tambopata (3 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Chegada a Puerto Maldonado – Navegação de barco a motor pelo rio Madre de Dios até o ecolodge – Trilha botânica e caminhada noturna na selva</li>\n	<li><strong>Dia 2:</strong> Expedição ao Lago Sandoval: observação de ariranhas gigantes, jacarés e macacos – Canopy walk nas pontes suspensas na copa das árvores</li>\n	<li><strong>Dia 3:</strong> Observação matinal de aves e colpa de papagaios – Café da manhã na selva – Retorno em barco a Puerto Maldonado e traslado ao aeroporto</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado na Selva de Tambopata:</h2>\n\n<h3>Dia 1: Chegada a Puerto Maldonado – Navegação até o Ecolodge</h3>\n<p>Recepção no aeroporto de Puerto Maldonado (voos vindos de Lima ou Cusco) e breve passagem pela sede para orientações. Embarcamos em canoa motorizada tradicional pelo caudaloso rio Madre de Dios até o nosso ecolodge. Almoço de boas-vindas com ingredientes típicos amazônicos embrulhados em folha de bananeira (juane). À tarde, fazemos uma caminhada introdutória pelas trilhas da floresta para conhecer castanheiras gigantes, lianas e plantas medicinais. À noite, realizamos uma caminhada noturna para avistar rãs coloridas, insetos bioluminescentes, aranhas e sons misteriosos da mata.</p>\n\n<h3>Dia 2: A Mágica do Lago Sandoval e Pontes Suspensas</h3>\n<p>Acordamos cedo ao som das aves e bugios. Navegamos até a entrada da Reserva Nacional Tambopata e caminhamos por uma trilha de madeira na mata inundada até o magnífico <strong>Lago Sandoval</strong>. Embarcamos em canoa a remo silenciosa para procurar a família residente de ariranhas gigantes (lontras gigantes de rio de até 2 metros), jacarés-açus, macacos-esquilo e a exótica ave pré-histórica cigana (hoatzin). Almoço no lodge. À tarde, subimos a uma torre de observação e caminhamos por passarelas suspensas a 30 metros de altura no dossel da floresta (canopy walk), com vista privilegiada para tucanos e araras.</p>\n\n<h3>Dia 3: Colpa de Papagaios – Retorno a Puerto Maldonado</h3>\n<p>Ao amanhecer, visitamos de barco uma colpa de argila na margem do rio, onde centenas de papagaios e periquitos verdes se reúnem em um espetáculo sonoro e visual para ingerir sais minerais da terra. Retornamos ao lodge para o café da manhã, preparamos a bagagem e navegamos de volta a Puerto Maldonado para traslado ao aeroporto para seu voo a Cusco ou Lima.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Recepção e traslados aeroporto / lodge / aeroporto em Puerto Maldonado</li>\n	<li>Transporte fluvial em canoas a motor privativas durante todo o programa</li>\n	<li>2 noites de hospedagem em ecolodge na floresta com banho privativo</li>\n	<li>Pensão completa (2 cafés da manhã, 2 almoços e 2 jantares amazônicos)</li>\n	<li>Todas as excursões ecológicas guiadas com guias naturalistas credenciados</li>\n	<li>Ingresso oficial para a Reserva Nacional Tambopata e Lago Sandoval</li>\n	<li>Equipamento de segurança e botas de borracha para as trilhas</li>\n</ul>', `importante` = '<h3>Dicas e recomendações essenciais:</h3>\n<ul>\n	<li>Vacina contra febre amarela recomendada (aplicada com antecedência mínima de 10 dias).</li>\n	<li>Levar repelente de mosquitos de alta eficácia (com DEET ou Icaridina) e protetor solar.</li>\n	<li>Roupas de cores neutras (evitar preto e cores berrantes): calças leves, camisas de manga longa de secagem rápida e capa de chuva.</li>\n	<li>Lanterna de mão ou de cabeça com pilhas extras e saco estanque para proteger eletrônicos da umidade.</li>\n</ul>' WHERE `id` = 17;

UPDATE `tourspt` SET `contenido` = '<h2>Huchuy Qosqo — Caminhada e Ruínas Incas nas Alturas (1 Dia)</h2>\n<p><strong>Huchuy Qosqo</strong>, que em idioma quéchua significa \"Pequeno Cusco\", é um sítio arqueológico inca impressionante e pouco explorado, cravado em um platô a 3.600 metros de altitude com uma vista panorâmica vertiginosa sobre todo o Vale Sagrado dos Incas e os picos nevados da Cordilheira Urubamba.</p>\n\n<p>Construída pelo oitavo imperador inca, <em>Huiracocha</em>, como seu refúgio real de descanso e retiro espiritual, a cidadela exibe construções monumentais de pedra polida perfeitamente conservadas no primeiro piso e adobes originais no piso superior — algo raríssimo na arquitetura incaica remanescente —, além de canais hidráulicos em pleno funcionamento e terraços agrícolas debruçados sobre o vale.</p>', `resumen` = '<h2>Resumo do Passeio (1 Dia):</h2>\n<ul>\n	<li><strong>06h30:</strong> Embarque em seu hotel em Cusco e traslado até a comunidade de Chinchero / Lagoa Piuray</li>\n	<li><strong>08h00:</strong> Início da caminhada por trechos originais de caminho inca e passo montanhoso a 4.100 m</li>\n	<li><strong>11h30:</strong> Chegada triunfal a Huchuy Qosqo com tour guiado completo e almoço picnic com vista</li>\n	<li><strong>14h00:</strong> Descida cênica até o vilarejo de Lamay no fundo do Vale Sagrado e traslado de volta a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<p>Buscamos você cedo em seu hotel em Cusco e seguimos em nossa van até a lagoa de Piuray, próxima a Chinchero. Iniciamos a caminhada subindo por um vale andino salpicado de campos de cultivo e pequenas casas de camponeses. Alcançamos o passo montanhoso a 4.100 metros, de onde contemplamos uma vista de tirar o fôlego da cadeia de montanhas nevadas de Vilcanota.</p>\n\n<p>A partir do passo, a trilha passa a seguir um antigo trecho empedrado do <strong>Qhapaq Ñan</strong> (Caminho Inca Real) que desce suavemente por um cânion de rochas avermelhadas, cruzando pontes incas até alcançar o portão de entrada de Huchuy Qosqo.</p>\n\n<p>Exploramos detalhadamente o palácio real de Huiracocha, o templo do sol, os depósitos agrícolas (qollqas) e a espetacular esplanada gramada. Saboreamos um delicioso almoço picnic apreciando o rio Urubamba centenas de metros abaixo de nossos pés.</p>\n\n<p>Após o descanso, iniciamos uma descida em zigue-zague de aproximadamente 2 horas até o vilarejo tradicional de Lamay, no fundo do vale, onde nosso veículo nos aguarda para retornar confortavelmente a Cusco por volta das 17h30.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Transporte turístico privativo de ida e volta desde seu hotel em Cusco</li>\n	<li>Guia oficial de turismo especializado em trilhas e história andina</li>\n	<li>Ingresso oficial de entrada para o complexo arqueológico de Huchuy Qosqo</li>\n	<li>Almoço gourmet tipo box lunch com opções nutritivas e frescas</li>\n	<li>Bastões de caminhada de apoio</li>\n	<li>Kit de primeiros socorros e oxigênio medicinal</li>\n</ul>', `importante` = '<h3>Recomendações:</h3>\n<ul>\n	<li>Nível físico moderado (cerca de 13 km no total, com subida inicial e descida acentuada até Lamay).</li>\n	<li>Usar botas ou tênis de trilha com boa tração para a descida de terra.</li>\n	<li>Levar agasalho em camadas (vento frio no passo e clima quente e ensolarado nas ruínas).</li>\n	<li>Mochila pequena com pelo menos 1,5 litro de água e protetor solar.</li>\n</ul>' WHERE `id` = 18;

UPDATE `tourspt` SET `contenido` = '<h2>Trilha Inca Clássica até Machu Picchu — 4 Dias e 3 Noites</h2>\n<p>A <strong>Trilha Inca Clássica de 4 Dias</strong> (Qhapaq Ñan) é indiscutivelmente a caminhada mais famosa e cobiçada de todo o continente americano. Eleita constantemente entre as melhores trilhas do mundo, ela combina ruínas arqueológicas misteriosas que não podem ser acessadas por nenhuma estrada, florestas subtropicais repletas de vida selvagem e a recompensa suprema: contemplar a cidadela de <strong>Machu Picchu</strong> ao raiar do dia através do <strong>Portal do Sol (Inti Punku)</strong>.</p>\n\n<p>Com a <strong>Pacha Mama Spirit</strong>, sua expedição conta com estrutura completa de acampamento, guias certificados de montanha, chefs de culinária andina e uma equipe exemplar de carregadores (porteadores) que garantem sua segurança, conforto e uma experiência humana transformadora.</p>', `resumen` = '<h2>Resumo do Roteiro (4 Dias / 3 Noites):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Km 82 – Patallacta – Acampamento Wayllabamba (12 km, moderado)</li>\n	<li><strong>Dia 2:</strong> Wayllabamba – Passo Warmiwañusqa (4.200 m) – Acampamento Pacaymayo (11 km, exigente)</li>\n	<li><strong>Dia 3:</strong> Pacaymayo – Runkurakay – Sayacmarca – Phuyupatamarca – Acampamento Wiñay Wayna (16 km, espetacular)</li>\n	<li><strong>Dia 4:</strong> Wiñay Wayna – Inti Punku – Machu Picchu – Tour guiado – Trem de retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado da Trilha Inca 4 Dias:</h2>\n\n<h3>Dia 1: Cusco – Km 82 – Wayllabamba</h3>\n<p>Buscamos você em seu hotel às 5h30 para seguir até o Km 82 (Piscacucho), ponto de largada oficial da Trilha Inca. Apresentamos os passaportes no controle oficial e começamos a caminhar às margens do rio Urubamba. Visitamos as imponentes ruínas de Patallacta e almoçamos em Miskay. À tarde, subimos suavemente pelo vale de Cusichaca até nosso primeiro acampamento no vilarejo andino de Wayllabamba (3.000 m).</p>\n\n<h3>Dia 2: O Desafio do Passo da Mulher Morta (Warmiwañusqa)</h3>\n<p>O dia mais desafiador da trilha. Acordamos cedo e iniciamos a subida constante através de florestas andinas até Llulluchapampa. Vencemos o famoso Passo Warmiwañusqa a 4.200 metros de altitude, com vistas panorâmicas indescritíveis dos nevados. Celebramos a conquista e iniciamos a descida por escadarias de pedra até o vale de Pacaymayo (3.500 m) para um almoço quente e merecido descanso.</p>\n\n<h3>Dia 3: A Rota Sagrada: Runkurakay, Sayacmarca e Wiñay Wayna</h3>\n<p>O trecho arqueológico mais deslumbrante da rota. Subimos passando pela torre de vigia inca de Runkurakay e cruzamos o segundo passo montanhoso (3.950 m). Visitamos a cidadela fortificada de Sayacmarca e caminhamos sobre calçamentos incas suspensos nas nuvens através de túneis entalhados na rocha. Almoçamos em Phuyupatamarca (\"A Cidade nas Nuvens\") e descemos mais de 3.000 degraus incas pela selva nublada até o magnífico sítio de Wiñay Wayna (2.650 m). Jantar de gala e celebração com os carregadores.</p>\n\n<h3>Dia 4: O Portal do Sol e Machu Picchu — Cusco</h3>\n<p>Despertamos antes das 4h00 e caminhamos cerca de 1h30 pela trilha cercada de orquídeas até o <strong>Inti Punku (Portal do Sol)</strong>. Ali, presenciamos o nascimento do dia iluminando as paredes de pedra e os terraços agrícolas de <strong>Machu Picchu</strong> — um dos momentos mais emocionantes de toda a vida de um viajante! Descemos à cidadela para a visita guiada completa de 2h30, almoçamos em Aguas Calientes e retornamos no trem turístico até Ollantaytambo, com traslado privativo ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Reunião prévia informativa em seu hotel em Cusco com o guia responsável</li>\n	<li>Transporte privativo de Cusco até o Km 82 e de Ollantaytambo de volta a Cusco</li>\n	<li>Permissão oficial do governo peruano para a Trilha Inca e ingresso para Machu Picchu</li>\n	<li>Guia oficial de montanha bilíngue credenciado de alta experiência</li>\n	<li>Chef de expedição e equipe de cozinha profissional</li>\n	<li>Equipe de carregadores (porteadores) para barracas, mantimentos e até 5 kg de bagagem pessoal</li>\n	<li>Barracas duplas espaçosas de 4 estações e isolantes térmicos</li>\n	<li>Todas as refeições durante a trilha (3 cafés da manhã, 3 almoços, 3 jantares)</li>\n	<li>Passagem de ônibus de descida de Machu Picchu para Aguas Calientes</li>\n	<li>Passagem de trem turístico de Aguas Calientes para Ollantaytambo</li>\n	<li>Cilindro de oxigênio medicinal e kit de emergência</li>\n</ul>', `importante` = '<h3>Avisos e regras oficiais:</h3>\n<ul>\n	<li><strong>Vagas rigorosamente limitadas:</strong> O governo peruano emite apenas 500 permissões por dia (incluindo guias e carregadores). É essencial reservar com 4 a 6 meses de antecedência.</li>\n	<li>A Trilha Inca fecha anualmente durante todo o mês de fevereiro para manutenção e conservação ambiental.</li>\n	<li>Obrigatório portar o passaporte físico original válido usado na emissão da permissão.</li>\n</ul>' WHERE `id` = 19;

UPDATE `tourspt` SET `contenido` = '<h2>Trilha Inca Curta até Machu Picchu — 2 Dias e 1 Noite</h2>\n<p>A <strong>Trilha Inca Curta de 2 Dias</strong> é a opção sob medida para quem deseja vivenciar a emoção autêntica de chegar a pé a Machu Picchu pelo lendário <strong>Portal do Sol (Inti Punku)</strong>, mas dispõe de poucos dias em seu roteiro ou não quer enfrentar as noites de acampamento da trilha longa.</p>\n\n<p>Neste trajeto condensed e espetacular, você desembarca do trem no Km 104, caminha cerca de 6 a 7 horas passando pelas fascinantes ruínas de <strong>Chachabamba</strong> e pelos imponentes terraços de <strong>Wiñay Wayna</strong>, contempla o pôr do sol exclusivo sobre Machu Picchu e pernoita confortavelmente em um hotel com banho quente em Aguas Calientes antes do tour guiado na manhã seguinte.</p>', `resumen` = '<h2>Resumo do Roteiro (2 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Trem até o Km 104 – Caminhada Chachabamba – Cascata e ruínas de Wiñay Wayna – Chegada ao Portal do Sol (Inti Punku) com vista de Machu Picchu – Descida a Aguas Calientes e hotel</li>\n	<li><strong>Dia 2:</strong> Subida em ônibus a Machu Picchu – Tour guiado minucioso de 2h30 – Trem de retorno a Ollantaytambo e traslado a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<h3>Dia 1: Cusco – Km 104 – Wiñay Wayna – Inti Punku – Aguas Calientes</h3>\n<p>Buscamos você cedo em seu hotel em Cusco e seguimos em van privativa até a estação de Ollantaytambo. Embarcamos no trem turístico até o Km 104 (Chachabamba, 2.100 m), ponto oficial de início da Trilha Inca Curta. Cruzamos a ponte sobre o rio Urubamba e visitamos o templo inca de Chachabamba. Iniciamos a subida gradual pela floresta nublada apreciando cachoeiras e dezenas de variedades de orquídeas nativas.</p>\n<p>Chegamos ao espetacular complexo arqueológico de <strong>Wiñay Wayna</strong> (2.650 m), com suas fontes cerimoniais de água e terrazas debruçadas sobre o vale, onde desfrutamos de um nutritivo box lunch. Continuamos caminhando por cerca de 1h30 por um caminho inca plano até alcançar o emblemático <strong>Inti Punku (Portal do Sol)</strong>. De lá, você terá a inesquecível visão panorâmica da cidadela de Machu Picchu banhada pela luz dourada do fim de tarde. Descemos de ônibus até Aguas Calientes para relaxar e pernoitar em hotel.</p>\n\n<h3>Dia 2: O Santuário de Machu Picchu – Retorno a Cusco</h3>\n<p>Após o café da manhã no hotel, tomamos o ônibus de subida até a entrada principal de Machu Picchu. Realizamos uma visita guiada completa de cerca de 2h30 conhecendo os mistérios da arquitetura, os setores residencial, industrial e os templos sagrados. Tempo livre para fotos. À tarde, descemos a Aguas Calientes, embarcamos no trem de volta a Ollantaytambo e nosso traslado privativo levará você com todo o conforto de volta ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Briefing preparatório em seu hotel em Cusco no dia anterior</li>\n	<li>Traslados privativos Cusco – Ollantaytambo e Ollantaytambo – Cusco</li>\n	<li>Passagem de trem turístico (Ollantaytambo até o Km 104)</li>\n	<li>Permissão oficial da Trilha Inca Curta e ingresso para Machu Picchu</li>\n	<li>Guia oficial de turismo credenciado bilíngue</li>\n	<li>Box lunch gourmet nutritivo para o Dia 1 e café da manhã no hotel no Dia 2</li>\n	<li>Passagens de ônibus de descida (Dia 1) e subida/descida (Dia 2) em Machu Picchu</li>\n	<li>1 noite de hotel selecionado em Aguas Calientes</li>\n	<li>Passagem de trem turístico de retorno a Ollantaytambo</li>\n	<li>Kit de primeiros socorros</li>\n</ul>', `importante` = '<h3>Informações importantes:</h3>\n<ul>\n	<li>As permissões para a Trilha Inca Curta são limitadas a 250 pessoas por dia: garanta sua vaga com antecedência.</li>\n	<li>A trilha fecha anualmente no mês de fevereiro para manutenção.</li>\n	<li>Obrigatório apresentar o passaporte original físico na entrada do Km 104 e em Machu Picchu.</li>\n</ul>' WHERE `id` = 20;

UPDATE `tourspt` SET `contenido` = '<h2>Trek Salkantay e Trilha Inca — A Experiência Suprema de 6 Dias</h2>\n<p>Esta é considerada por especialistas em trekking a <strong>expedição definitiva nos Andes peruanos</strong>: a união perfeita entre a grandiosidade selvagem do <strong>Nevado Salkantay</strong> (com suas geleiras e passos acima de 5.000 metros) e a mística histórica dos caminhos empedrados da autêntica <strong>Trilha Inca Clássica</strong>.</p>\n\n<p>Ao longo de 6 dias épicos, você cruzará paisagens glaciais imponentes aos pés do pico sagrado do Apu Salkantay (6.271 m), contornará a deslumbrante rota de Sisaypampa e entrará diretamente na Trilha Inca original através do Passo Incachiriasca, visitando sítios arqueológicos como Paucarcancha, Runkurakay, Sayacmarca e Wiñay Wayna antes de ingressar triunfalmente em <strong>Machu Picchu</strong> pelo Portal do Sol.</p>', `resumen` = '<h2>Resumo do Roteiro (6 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Mollepata – Soraypampa – Lagoa Humantay – Acampamento Suyrococha</li>\n	<li><strong>Dia 2:</strong> Suyrococha – Passo Incachiriasca (5.100 m) – Sisaypampa</li>\n	<li><strong>Dia 3:</strong> Sisaypampa – Canal Inca – Ruínas de Paucarcancha – Encontro com a Trilha Inca em Wayllabamba</li>\n	<li><strong>Dia 4:</strong> Wayllabamba – Passo Warmiwañusqa (4.200 m) – Pacaymayo</li>\n	<li><strong>Dia 5:</strong> Pacaymayo – Sayacmarca – Phuyupatamarca – Wiñay Wayna</li>\n	<li><strong>Dia 6:</strong> Wiñay Wayna – Portal do Sol (Inti Punku) – Machu Picchu Completo – Retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado da Expedição Salkantay + Trilha Inca:</h2>\n\n<h3>Dia 1: Cusco – Mollepata – Soraypampa – Suyrococha</h3>\n<p>Saída às 5h00 de Cusco em nossa van privativa até Mollepata para o café da manhã. Seguimos até Challacancha para iniciar a caminhada até Soraypampa, onde almoçamos. À tarde, subimos até a deslumbrante Lagoa Humantay e continuamos nossa subida até o acampamento de alta montanha em Suyrococha (4.200 m), desfrutando de um jantar quente sob as estrelas aos pés do imenso glaciar Salkantay.</p>\n\n<h3>Dia 2: Conquista do Passo Incachiriasca (5.100 m) – Sisaypampa</h3>\n<p>O dia mais elevado e emocionante da expedição. Subimos até o monumental <strong>Passo Incachiriasca</strong> (5.100 m), o ponto mais alto de toda a rota, onde tocamos as geleiras eternas e contemplamos as profundezas dos vales andinos. Descemos suavemente pelo vale de Sisaypampa, observando condores e rebanhos de alpacas até nosso segundo acampamento em uma planície cercada por cachoeiras.</p>\n\n<h3>Dia 3: Sisaypampa – Paucarcancha – Wayllabamba</h3>\n<p>Caminhamos ao longo de um antigo canal de irrigação inca até o impressionante sítio arqueológico de <strong>Paucarcancha</strong>, onde as culturas inca e pré-inca se encontram na confluência de dois vales. Almoçamos junto às ruínas e nos conectamos oficialmente à rota da Trilha Inca Clássica, seguindo até nosso acampamento em Wayllabamba.</p>\n\n<h3>Dia 4: Passo Warmiwañusqa (4.200 m) – Pacaymayo</h3>\n<p>Acordamos cedo e enfrentamos a clássica subida até o Passo da Mulher Morta (4.200 m). Após apreciar a vista panorâmica sobre os dois vales, iniciamos a descida por escadarias de pedra até o acampamento de Pacaymayo para almoçar e descansar.</p>\n\n<h3>Dia 5: A Rota Imperial: Sayacmarca, Phuyupatamarca e Wiñay Wayna</h3>\n<p>Dia repleto de sítios arqueológicos: visitamos a fortaleza semicircular de Runkurakay, cruzamos o segundo passo, exploramos a enigmática cidadela de Sayacmarca e atravessamos a floresta nublada até Phuyupatamarca. Descemos até Wiñay Wayna para nosso último jantar de acampamento e celebração com os carregadores.</p>\n\n<h3>Dia 6: O Portal do Sol e Machu Picchu — Retorno a Cusco</h3>\n<p>Caminhamos bem cedo até o <strong>Inti Punku (Portal do Sol)</strong> para assistir ao sol iluminar Machu Picchu. Descemos à cidade sagrada para o tour guiado de 2h30. À tarde, descida a Aguas Calientes, embarque no trem panorâmico para Ollantaytambo e traslado privativo ao seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui esta grande expedição:</h3>\n<ul>\n	<li>Briefing minucioso em seu hotel em Cusco antes da partida</li>\n	<li>Transporte privativo completo de ida e volta</li>\n	<li>Permissões oficiais do circuito Salkantay e da Trilha Inca Clássica</li>\n	<li>Ingresso oficial para o santuário de Machu Picchu</li>\n	<li>Guia oficial de montanha bilíngue de alta qualificação</li>\n	<li>Chef profissional de alta montanha e ajudantes</li>\n	<li>Cavalos de carga para os primeiros dias e equipe de carregadores para a Trilha Inca</li>\n	<li>Barracas duplas 4 estações, isolantes térmicos e barraca-refeitório completa</li>\n	<li>Todas as refeições durante os 6 dias de trilha (5 cafés da manhã, 5 almoços, 5 jantares)</li>\n	<li>Passagem de ônibus de descida em Machu Picchu</li>\n	<li>Passagem de trem turístico de retorno a Ollantaytambo</li>\n	<li>Cilindro de oxigênio de emergência e primeiros socorros</li>\n</ul>', `importante` = '<h3>Requisitos fundamentais:</h3>\n<ul>\n	<li>Exige excelente condição física e experiência prévia em caminhadas em altitude (atinge 5.100 m).</li>\n	<li>Aclimatação mínima obrigatória de 3 dias em Cusco antes de iniciar a expedição.</li>\n	<li>Reservar com 3 a 5 meses de antecedência devido à exigência das permissões limitadas da Trilha Inca.</li>\n</ul>' WHERE `id` = 21;

UPDATE `tourspt` SET `contenido` = '<h2>Cachicata Trek — A Rota dos Construtores Incas (3 Dias e 2 Noites)</h2>\n<p>O <strong>Cachicata Trek</strong> (conhecido também como a Trilha da Pedreira Inca) é uma das rotas de trekking mais autênticas, cênicas e fora do circuito turístico tradicional da região de Cusco. Em vez de caminhar pelas rotas concorridas, você seguirá os passos dos próprios arquitetos e engenheiros do Império Inca.</p>\n\n<p>A trilha percorre a encosta sul do Vale Sagrado até a imensa <strong>pedreira de Cachicata</strong>, de onde saíram os colossais blocos de granito rosa que foram transportados através do vale e do rio para construir a lendária fortaleza de <strong>Ollantaytambo</strong>. Pelo caminho, você visitará antigas múmias incas em cavernas sagradas (chullpas), a impressionante cascata de Perolniyoc, sítios arqueológicos intocados e contemplará o vale sagrado de uma perspectiva panorâmica exclusiva.</p>', `resumen` = '<h2>Resumo do Roteiro Cachicata 3 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Vilarejo de Soqma – Cascata de Perolniyoc – Sítio Arqueológico de Rayan – Acampamento (3.700 m)</li>\n	<li><strong>Dia 2:</strong> Rayan – Passo Puccaqasa (4.400 m) – Pedreira Inca de Cachicata – Pôr do sol sobre Ollantaytambo</li>\n	<li><strong>Dia 3:</strong> Descida a Ollantaytambo – Tour pela fortaleza inca – Trem a Aguas Calientes – Machu Picchu (ou retorno a Cusco)</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado do Cachicata Trek:</h2>\n\n<h3>Dia 1: Cusco – Cascata de Perolniyoc – Rayan</h3>\n<p>Buscamos você em seu hotel em Cusco e seguimos em van privativa pelo Vale Sagrado até a pequena comunidade de Soqma (2.950 m). Começamos a caminhada subindo suavemente por um vale verdejante até a cinematográfica cascata de Perolniyoc, que despenca por cerca de 100 metros sobre o vale. Acima da cachoeira, exploramos o sítio arqueológico de Raqaypata, uma antiga fortaleza inca. Continuamos subindo até nosso primeiro acampamento na comunidade andina de Rayan (3.700 m), desfrutando de um pôr do sol dourado e jantar quente preparado pelo nosso chef.</p>\n\n<h3>Dia 2: Rayan – Passo de Choquetakarpo – Pedreiras de Cachicata</h3>\n<p>Após café da manhã nutritivo, subimos até o Passo Puccaqasa (4.400 m) para contemplar as imponentes geleiras Veronica e Chicón. Descemos em direção à famosa <strong>Pedreira Inca de Cachicata</strong>, onde enormes blocos de pedra talhada ainda jazem no chão exatamente como foram deixados no momento da chegada dos conquistadores espanhóis. Visitamos antigos túmulos incas (chullpas), a Casa do Inca e uma rampa gigantesca usada para rolar os monólitos montanha abaixo. Acampamos com vista panorâmica frontal para a fortaleza de Ollantaytambo iluminada à noite.</p>\n\n<h3>Dia 3: Cachicata – Ollantaytambo – Cusco (ou Machu Picchu)</h3>\n<p>Descemos por uma trilha cênica até o rio Vilcanota, cruzando a ponte inca até Ollantaytambo. Realizamos um tour guiado pelas ruelas e fontes sagradas da fortaleza de Ollantaytambo. À tarde, você poderá embarcar no trem turístico para visitar Machu Picchu ou retornar em nossa van privativa para o seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Transporte privativo de ida e volta desde seu hotel em Cusco</li>\n	<li>Guia oficial de montanha bilíngue credenciado e especialista em engenharia inca</li>\n	<li>Chef profissional de trekking e equipe de apoio</li>\n	<li>Cavalos de carga e tropeiros para transporte das barracas, comida e até 7 kg de bagagem por cliente</li>\n	<li>Barracas duplas 4 estações de montanha, colchonete isolante e barraca-refeitório</li>\n	<li>Todas as refeições durante a trilha (2 cafés da manhã, 3 almoços, 2 jantares)</li>\n	<li>Visita guiada às cascatas de Perolniyoc, ruínas e à pedreira de Cachicata</li>\n	<li>Kit de primeiros socorros e cilindro de oxigênio</li>\n</ul>', `importante` = '<h3>Vantagens deste roteiro:</h3>\n<ul>\n	<li><strong>Disponibilidade o ano todo:</strong> Não exige as permissões rígidas da Trilha Inca tradicional, sendo uma excelente opção para reservas de última hora.</li>\n	<li>Nível de condicionamento físico moderado a bom (altitude máxima de 4.400 m).</li>\n	<li>Recomenda-se aclimatação mínima de 2 dias em Cusco antes da partida.</li>\n</ul>' WHERE `id` = 22;

UPDATE `tourspt` SET `contenido` = '<h2>Trek Circuito Ausangate e Montanha de 7 Cores — 3 Dias e 2 Noites</h2>\n<p>O <strong>Apu Ausangate</strong> (6.384 m) é o pico nevado sagrado mais importante de todo o sul do Peru, reverenciado pelos povos quéchuas há milênios como o criador e protetor das águas, das lhamas e da vida nos Andes.</p>\n\n<p>Esta expedição de alta montanha de 3 dias é uma das jornadas mais puras e selvagens da América do Sul. Você caminhará entre lagoas glaciais de tons azul-turquesa e verde-esmeralda, cruzará passos andinos a mais de 5.000 metros de altitude, relaxará em piscinas de águas termais aos pés de paredões de gelo eterno e alcançará a famosa <strong>Montanha de 7 Cores (Vinicunca)</strong> nas primeiras horas da manhã, antes de qualquer outro grupo de turistas!</p>', `resumen` = '<h2>Resumo do Roteiro Ausangate 3 Dias:</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Cusco – Povoado de Tinki – Banhos Termais de Upis aos pés da geleira Ausangate (acampamento a 4.400 m)</li>\n	<li><strong>Dia 2:</strong> Upis – Passo Arapa (4.750 m) – Lagoas Pucacocha – Passo Pucacocha (5.000 m) – Acampamento Ananta (4.500 m)</li>\n	<li><strong>Dia 3:</strong> Ananta – Mirante da Montanha de 7 Cores (Vinicunca) ao amanhecer – Vale Vermelho – Retorno a Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado da Expedição Ausangate:</h2>\n\n<h3>Dia 1: Cusco – Tinki – Termas de Upis</h3>\n<p>Saída às 5h00 de Cusco em van privativa pelo vale sul até a comunidade de Tinki (3.800 m). Encontramos nossos arrieiros e cavalos de carga. Iniciamos a caminhada subindo por uma planície andina com vista frontal impressionante da imensa geleira do Ausangate. Chegamos a Upis (4.400 m) para o almoço. À tarde, relaxamos nas piscinas termais naturais ao ar livre contemplando a parede de gelo do nevado. Jantar quente e acampamento sob um dos céus mais estrelados do planeta.</p>\n\n<h3>Dia 2: Upis – Passo Arapa – Lagoas de Pucacocha – Ananta</h3>\n<p>Após café da manhã reforçado, subimos até o Passo Arapa (4.750 m) com vistas arrebatadoras de vales desérticos policromáticos. Descemos até as cinematográficas lagoas de Pucacocha, onde blocos de gelo frequentemente se desprendem da geleira com estrondo caindo na água turquesa. Após o almoço, vencemos o segundo passo a quase 5.000 metros e descemos suavemente até o acampamento de Ananta (4.500 m).</p>\n\n<h3>Dia 3: Montanha de 7 Cores (Vinicunca) – Vale Vermelho – Cusco</h3>\n<p>Acordamos antes das 5h00 e subimos pelo vale até o mirante da <strong>Montanha de 7 Cores (Vinicunca, 5.200 m)</strong>. Chegamos nas primeiras horas do dia, desfrutando da montanha arco-íris em silêncio absoluto e com iluminação perfeita para fotos, muito antes da chegada das excursões de bate-volta que saem de Cusco! Em seguida, caminhamos pelo surreal <strong>Vale Vermelho</strong>, almoçamos em nosso ponto de apoio e retornamos confortavelmente em nossa van privativa a Cusco, chegando por volta das 17h00.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Transporte turístico privativo de ida e volta desde seu hotel em Cusco</li>\n	<li>Guia de alta montanha oficial bilíngue credenciado e nativo quéchua</li>\n	<li>Chef de expedição profissional e alimentação completa (2 cafés da manhã, 3 almoços, 2 jantares)</li>\n	<li>Cavalos de carga para levar barracas, comida e até 8 kg de bagagem pessoal por cliente</li>\n	<li>Barracas duplas 4 estações de alta montanha, isolantes térmicos e barraca-refeitório</li>\n	<li>Entrada para as termas de Upis e taxas das comunidades de Ausangate e Vinicunca</li>\n	<li>Bastões de caminhada inclusos</li>\n	<li>Cilindro de oxigênio de alta capacidade e maleta de primeiros socorros</li>\n</ul>', `importante` = '<h3>Exigências físicas:</h3>\n<ul>\n	<li>Exige excelente condicionamento físico e resistência a altitudes elevadas (caminha-se entre 4.400 m e 5.200 m).</li>\n	<li>Aclimatação prévia obrigatória de pelo menos 3 dias em Cusco antes de iniciar a expedição.</li>\n	<li>Trazer saco de dormir para temperaturas negativas (até -15°C) e roupas térmicas adequadas para o frio rigoroso da noite andina.</li>\n</ul>' WHERE `id` = 23;

UPDATE `tourspt` SET `contenido` = '<h2>Amazônia e Machu Picchu — O Peru Completo em 10 Dias</h2>\n<p>Este pacote exclusivo de 10 dias une dois dos ecossistemas mais fascinantes, míticos e preservados da Terra: a exuberância intocada da <strong>Floresta Amazônica peruana em Tambopata</strong> e o esplendor sagrado dos <strong>Andes e Machu Picchu</strong>.</p>\n\n<p>Com toda a logística perfeitamente organizada pela <strong>Pacha Mama Spirit</strong> — incluindo voos domésticos, traslados privativos, ecolodge de selva, hotéis confortáveis e passeios guiados por especialistas —, você vivenciará desde o encontro com ariranhas gigantes e tucanos na Amazônia até a magia arquitetônica e espiritual da Cidade Perdida dos Incas.</p>', `resumen` = '<h2>Resumo do Roteiro (10 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Chegada à capital gastronômica Lima – Traslado ao hotel em Miraflores</li>\n	<li><strong>Dias 2 e 3:</strong> Voo para Puerto Maldonado – Imersão na Amazônia de Tambopata: ecolodge, Lago Sandoval e canopy walk</li>\n	<li><strong>Dia 4:</strong> Voo da Amazônia para Cusco – Tarde livre para aclimatação e descanso</li>\n	<li><strong>Dia 5:</strong> City Tour Arqueológico em Cusco (Sacsayhuamán e Qoricancha)</li>\n	<li><strong>Dia 6:</strong> Vale Sagrado dos Incas (Pisac, Urubamba e Ollantaytambo) – Trem a Aguas Calientes</li>\n	<li><strong>Dia 7:</strong> Machu Picchu Maravilha do Mundo – Retorno a Cusco</li>\n	<li><strong>Dia 8:</strong> Dia livre em Cusco para passeios opcionais (Montanha de 7 Cores ou Humantay)</li>\n	<li><strong>Dia 9:</strong> Voo de Cusco a Lima – City Tour pela Lima Colonial e Moderna</li>\n	<li><strong>Dia 10:</strong> Lima – Traslado ao aeroporto para voo internacional de volta</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<h3>Dia 1: Chegada a Lima</h3>\n<p>Recepção no aeroporto de Lima e traslado privativo ao hotel em Miraflores. Tarde livre para passear e desfrutar dos premiados restaurantes peruanos.</p>\n\n<h3>Dias 2 e 3: Aventura na Selva de Tambopata</h3>\n<p>Voo matinal para Puerto Maldonado. Embarcamos em canoa a motor pelo rio Madre de Dios até o ecolodge. Exploramos trilhas na mata primária, fazemos caminhadas noturnas e navegamos em canoa a remo no espelho d\'água do <strong>Lago Sandoval</strong>, avistando lontras gigantes de rio, macacos e jacarés. Caminhamos pelas pontes suspensas na copa das árvores a 30 metros de altura.</p>\n\n<h3>Dia 4: Da Amazônia para o Coração dos Andes</h3>\n<p>Café da manhã na selva, traslado ao aeroporto de Puerto Maldonado e voo direto para Cusco (3.400 m). Recepção acolhedora e traslado ao hotel para descanso e aclimatação com chá de coca.</p>\n\n<h3>Dia 5: Cusco Imperial e Sítios Arqueológicos</h3>\n<p>À tarde, tour guiado pelo Templo do Sol (Qoricancha) e as quatro fortalezas incas nos arredores: Sacsayhuamán, Qenqo, Puka Pukara e Tambomachay.</p>\n\n<h3>Dia 6: Vale Sagrado dos Incas – Aguas Calientes</h3>\n<p>Excursão pelo Vale Sagrado visitando Pisac e sua feira de artesanato, almoço buffet em Urubamba e visita à fortaleza viva de Ollantaytambo. Embarque no trem panorâmico rumo a Aguas Calientes.</p>\n\n<h3>Dia 7: Machu Picchu — A Cidade Perdida dos Incas</h3>\n<p>Subida em ônibus até a cidadela de Machu Picchu para o tour guiado completo de cerca de 2h30. Tempo livre para fotos inesquecíveis. À tarde, trem de volta a Ollantaytambo e traslado privativo a Cusco.</p>\n\n<h3>Dia 8: Dia Livre em Cusco</h3>\n<p>Dia livre para explorar os ateliês de arte de San Blas, fazer compras no Mercado San Pedro ou realizar uma excursão à Montanha de 7 Cores ou à Lagoa Humantay.</p>\n\n<h3>Dia 9: Cusco – Lima Colonial e Moderna</h3>\n<p>Voo de retorno a Lima. City tour conhecendo o centro histórico (Plaza Mayor, Catedral e Catacumbas de São Francisco) e os modernos bairros litorâneos de San Isidro e Miraflores.</p>\n\n<h3>Dia 10: Retorno ao Brasil</h3>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Lima para conexão internacional.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Voos domésticos inclusos (Lima – Puerto Maldonado – Cusco – Lima)</li>\n	<li>Todos os traslados privativos terrestres e fluviais em todas as cidades</li>\n	<li>2 noites em ecolodge na selva com pensão completa e excursões guiadas</li>\n	<li>5 noites de hotel em Cusco com café da manhã</li>\n	<li>1 noite de hotel em Aguas Calientes com café da manhã</li>\n	<li>1 noite de hotel em Lima com café da manhã</li>\n	<li>City tour em Cusco com ingressos e Vale Sagrado com almoço buffet</li>\n	<li>Passagens de trem turístico ida e volta para Machu Picchu</li>\n	<li>Ingresso oficial para Machu Picchu e ônibus subida/descida</li>\n	<li>City tour em Lima com entradas</li>\n</ul>', `importante` = '<h3>Recomendações:</h3>\n<ul>\n	<li>Vacina contra febre amarela recomendada para a visita a Tambopata.</li>\n	<li>Levar roupas leves de secagem rápida e repelente para a selva, e agasalhos para o frio noturno de Cusco.</li>\n	<li>Passaporte original válido ou RG brasileiro em excelente estado.</li>\n</ul>' WHERE `id` = 24;

UPDATE `tourspt` SET `contenido` = '<h2>Expedição Peru: Amazônia e Trilha Inca — 11 Dias de Pura Aventura</h2>\n<p>Para quem busca vivenciar o Peru em sua máxima autenticidade e contato profundo com a natureza: esta expedição de 11 dias une a rica vida selvagem da <strong>Floresta Amazônica de Tambopata</strong> com a consagração física e histórica da <strong>Trilha Inca Clássica de 4 Dias a pé até Machu Picchu</strong>.</p>\n\n<p>Desde a navegação em canoas em meio a lontras gigantes e araras na selva até a conquista do Passo Warmiwañusqa a 4.200 metros de altitude e a entrada emocionante no Portal do Sol de Machu Picchu, este roteiro proporciona a viagem de aventura de uma vida inteira!</p>', `resumen` = '<h2>Resumo do Roteiro (11 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Chegada a Lima e pernoite em Miraflores</li>\n	<li><strong>Dias 2 e 3:</strong> Voo para Puerto Maldonado – 2 dias e 2 noites em ecolodge na Reserva Tambopata (Lago Sandoval e caminhadas na selva)</li>\n	<li><strong>Dia 4:</strong> Voo da Amazônia para Cusco – Aclimatação e briefing da trilha</li>\n	<li><strong>Dia 5:</strong> Trilha Inca Dia 1: Cusco – Km 82 – Patallacta – Acampamento Wayllabamba</li>\n	<li><strong>Dia 6:</strong> Trilha Inca Dia 2: Wayllabamba – Passo da Mulher Morta (4.200 m) – Acampamento Pacaymayo</li>\n	<li><strong>Dia 7:</strong> Trilha Inca Dia 3: Pacaymayo – Sayacmarca – Phuyupatamarca – Acampamento Wiñay Wayna</li>\n	<li><strong>Dia 8:</strong> Trilha Inca Dia 4: Wiñay Wayna – Portal do Sol – Machu Picchu Completo – Retorno a Cusco em hotel</li>\n	<li><strong>Dia 9:</strong> Dia de descanso e celebração em Cusco</li>\n	<li><strong>Dia 10:</strong> Voo de Cusco a Lima – Tarde livre na capital gastronômica</li>\n	<li><strong>Dia 11:</strong> Lima – Traslado ao aeroporto para retorno</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<h3>Dias 1 a 3: Da Capital à Amazônia de Tambopata</h3>\n<p>Chegada a Lima e conexão aérea para Puerto Maldonado. Embarcamos pelo rio Madre de Dios rumo ao nosso ecolodge sustentável. Durante 2 dias e 2 noites, exploramos os segredos da mata primária: caminhada noturna para observação de fauna, navegação silenciosa pelo <strong>Lago Sandoval</strong> em busca de ariranhas gigantes e jacarés, e passarelas no dossel da floresta.</p>\n\n<h3>Dia 4: Da Selva para Cusco — Preparação para a Trilha</h3>\n<p>Voo para Cusco. Recepção e traslado ao hotel. Tarde dedicada ao descanso, hidratação e reunião técnica detalhada com nosso guia de montanha sobre os 4 dias de caminhada pela Trilha Inca.</p>\n\n<h3>Dias 5 a 8: A Grande Jornada da Trilha Inca até Machu Picchu</h3>\n<p>Quatro dias lendários percorrendo o Qhapaq Ñan: partimos do Km 82, subimos pelo vale até Wayllabamba, superamos o mítico Passo Warmiwañusqa a 4.200 m, exploramos cidadelas incas suspensas nas nuvens (Runkurakay, Sayacmarca, Phuyupatamarca e Wiñay Wayna) com suporte de nossos carregadores e chefs de montanha. No 8º dia, cruzamos o <strong>Inti Punku (Portal do Sol)</strong> ao amanhecer para contemplar Machu Picchu! Tour guiado de 2h30 e retorno triunfal de trem e van privativa ao hotel em Cusco para um merecido banho quente e comemoração.</p>\n\n<h3>Dias 9 a 11: Cusco, Lima e Retorno</h3>\n<p>Dia 9 livre para massagens, restaurantes e compras em Cusco. No Dia 10, voo para Lima para desfrutar da culinária litorânea. No Dia 11, traslado privativo ao aeroporto de Lima para seu voo internacional.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Voos domésticos inclusos (Lima – Puerto Maldonado – Cusco – Lima)</li>\n	<li>Todos os traslados privativos terrestres e fluviais durante toda a rota</li>\n	<li>2 noites em ecolodge na selva com pensão completa e atividades guiadas</li>\n	<li>4 noites de hotel em Cusco com café da manhã</li>\n	<li>1 noite de hotel em Lima com café da manhã</li>\n	<li>Permissão oficial do governo peruano para a Trilha Inca Clássica de 4 dias</li>\n	<li>Equipe completa de trilha: guia oficial de montanha, chef de expedição e carregadores (porteadores)</li>\n	<li>Barracas duplas de alta montanha, isolantes térmicos e refeições completas na trilha</li>\n	<li>Ingresso para Machu Picchu, ônibus de descida e trem turístico de retorno</li>\n</ul>', `importante` = '<h3>Requisitos fundamentais:</h3>\n<ul>\n	<li><strong>Reserva com 4 a 6 meses de antecedência:</strong> As permissões da Trilha Inca são nominais e esgotam com meses de antecedência.</li>\n	<li>Bom preparo físico para 4 dias consecutivos de trekking com mochila de ataque.</li>\n	<li>Vacina contra febre amarela recomendada para a visita a Tambopata.</li>\n</ul>' WHERE `id` = 25;

UPDATE `tourspt` SET `contenido` = '<h2>Machu Picchu Luxury — Belmond Sanctuary Lodge (3 Dias e 2 Noites)</h2>\n<p>Uma experiência incomparável de exclusividade, sofisticação e conforto supremo. O <strong>Belmond Sanctuary Lodge</strong> é o <strong>único hotel situado diretamente ao lado da entrada da cidadela de Machu Picchu</strong>, no topo da montanha, permitindo que você desfrute da maravilha inca sem multidões, com duas visitas exclusivas e serviço de hotelaria de luxo internacional 5 estrelas.</p>\n\n<p>Esqueça as filas de ônibus e o cansaço do bate-volta: você estará a poucos passos do portal sagrado dos incas, com jardins privativos de orquídeas com vista para o Huayna Picchu, gastronomia andina de autor premiada, viagens no exclusivo trem panorâmico <strong>Vistadome ou Hiram Bingham</strong> e guia privativo dedicado.</p>', `resumen` = '<h2>Resumo da Experiência Luxury (3 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Traslado VIP em Cusco – Trem de luxo até Aguas Calientes – Subida exclusiva e check-in no Belmond Sanctuary Lodge – Primeira visita a Machu Picchu na tranquilidade do entardecer</li>\n	<li><strong>Dia 2:</strong> Alvorecer em Machu Picchu com entrada privativa – Subida opcional ao Huayna Picchu – Tarde relaxante nos jardins de orquídeas e spa do lodge – Jantar gourmet</li>\n	<li><strong>Dia 3:</strong> Café da manhã gourmet com vista para as montanhas – Manhã de contemplação – Trem de retorno em primeira classe e traslado privativo ao hotel em Cusco</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado da Experiência Luxury:</h2>\n\n<h3>Dia 1: Cusco – Trem de Luxo – Belmond Sanctuary Lodge</h3>\n<p>Nosso serviço privativo VIP buscará você em seu hotel em Cusco para o traslado até a estação de trem. Embarcamos no elegante trem panorâmico com serviço de bordo diferenciado, apreciando o cânion do rio Urubamba. Ao chegar a Aguas Calientes, nossa equipe conduz você diretamente ao ônibus privativo que sobe até o <strong>Belmond Sanctuary Lodge</strong>. Após o check-in e coquetel de boas-vindas com vista para as montanhas sagradas, realizamos nossa primeira visita privativa a Machu Picchu nas horas mágicas do final da tarde, quando a maior parte dos turistas já partiu. À noite, jantar degustação com vinhos selecionados no restaurante Tampu do hotel.</p>\n\n<h3>Dia 2: O Alvorecer Mágico em Machu Picchu</h3>\n<p>Acorde a poucos passos da entrada de Machu Picchu e seja um dos primeiros a entrar na cidadela sagrada quando os portões se abrem. Realizamos um tour guiado privativo e aprofundado pelos setores mais reservados do complexo. Aqueles que desejarem poderão subir o pico de <strong>Huayna Picchu</strong> para uma vista aérea monumental. À tarde, desfrute de uma massagem relaxante no spa do hotel ou tome um drinque nos terraços cercados por colibris e orquídeas nativas. Pernoite no Sanctuary Lodge.</p>\n\n<h3>Dia 3: Retorno a Cusco em Primeira Classe</h3>\n<p>Desfrute de um café da manhã refinado com vista panorâmica. Manhã livre para contemplar a energia do local. À tarde, descemos a Aguas Calientes para embarcar no trem de luxo de volta a Ollantaytambo, onde nosso motorista privativo o aguardará para o traslado até seu hotel em Cusco.</p>', `incluidos` = '<h3>O que inclui esta experiência de alto padrão:</h3>\n<ul>\n	<li>Todos os traslados privativos em veículos executivos de luxo em Cusco e Vale Sagrado</li>\n	<li>Passagens de trem de primeira classe panorâmico (Vistadome Observatório ou opção Hiram Bingham)</li>\n	<li>2 noites de hospedagem no exclusivo Belmond Sanctuary Lodge com café da manhã e jantar gourmet</li>\n	<li>Duas entradas oficiais exclusivas para Machu Picchu em horários privilegiados</li>\n	<li>Guia oficial de turismo privativo dedicado exclusivamente a você durante os passeios</li>\n	<li>Todas as passagens de ônibus VIP de subida e descida</li>\n	<li>Atendimento de concierge 24 horas por dia da Pacha Mama Spirit</li>\n</ul>', `importante` = '<h3>Observações exclusivas:</h3>\n<ul>\n	<li>O Belmond Sanctuary Lodge possui apenas cerca de 30 quartos: a reserva deve ser realizada com 4 a 6 meses de antecedência mínima.</li>\n	<li>Obrigatório apresentar passaporte físico original válido.</li>\n	<li>Possibilidade de upgrade para o lendário trem de superluxo Belmond Hiram Bingham.</li>\n</ul>' WHERE `id` = 26;

UPDATE `tourspt` SET `contenido` = '<h2>A Aventura Definitiva: Amazônia, Trilha Inca e Lago Titicaca — 15 Dias</h2>\n<p>O <strong>pacote definitivo e mais completo do Peru</strong>. Quinze dias inesquecíveis explorando as três grandes regiões geográficas e culturais do país: a costa do Pacífico em <strong>Lima</strong>, a floresta primária da <strong>Amazônia em Tambopata</strong>, a lendária <strong>Trilha Inca a pé até Machu Picchu</strong> e o altiplano sagrado do <strong>Lago Titicaca em Puno</strong>.</p>\n\n<p>Projetado para viajantes apaixonados que não querem deixar nenhum grande tesouro de fora, este roteiro equilibra vida selvagem, grandes trilhas históricas, civilizações ancestrais e o conforto de uma operação turística impecável e ética.</p>', `resumen` = '<h2>Resumo do Roteiro (15 Dias):</h2>\n<ul>\n	<li><strong>Dias 1 a 4:</strong> Lima e Amazônia (Tambopata: ecolodge, Lago Sandoval e canopy)</li>\n	<li><strong>Dia 5:</strong> Voo da selva para Cusco – Tarde livre de aclimatação</li>\n	<li><strong>Dia 6:</strong> Vale Sagrado dos Incas (Pisac, Urubamba e Ollantaytambo)</li>\n	<li><strong>Dias 7 a 10:</strong> Expedição Trilha Inca Clássica de 4 Dias a pé até Machu Picchu</li>\n	<li><strong>Dia 11:</strong> Dia de descanso e celebração em Cusco</li>\n	<li><strong>Dia 12:</strong> Rota do Sol: Ônibus cênico de Cusco até Puno com visitas guiadas</li>\n	<li><strong>Dia 13:</strong> Lago Titicaca: Ilhas Flutuantes dos Uros e pernoite em Taquile</li>\n	<li><strong>Dia 14:</strong> Taquile – Puno – Sítio funerário de Sillustani – Voo de volta a Lima</li>\n	<li><strong>Dia 15:</strong> Lima – Traslado ao aeroporto para retorno internacional</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado de 15 Dias:</h2>\n\n<h3>Dias 1 a 4: Lima e Floresta Amazônica de Tambopata</h3>\n<p>Chegada a Lima e voo para Puerto Maldonado no Dia 2. Três dias e duas noites em ecolodge sustentável navegando pelo rio Madre de Dios, buscando ariranhas gigantes e jacarés no Lago Sandoval e caminhando por pontes suspensas a 30 metros de altura no dossel da floresta.</p>\n\n<h3>Dias 5 e 6: Cusco e o Vale Sagrado dos Incas</h3>\n<p>Voo para Cusco para aclimatação. No Dia 6, exploramos o fértil Vale Sagrado dos Incas: visitamos as ruínas e mercado de Pisac, almoçamos em Urubamba e conhecemos a fortaleza viva de Ollantaytambo.</p>\n\n<h3>Dias 7 a 10: A Lendária Trilha Inca até Machu Picchu</h3>\n<p>Quatro dias épicos caminhando pelo Qhapaq Ñan: partimos do Km 82, subimos até o Passo Warmiwañusqa (4.200 m), visitamos sítios incas inacessíveis por estradas (Sayacmarca, Phuyupatamarca, Wiñay Wayna) e cruzamos o Portal do Sol ao amanhecer para contemplar Machu Picchu! Tour guiado de 2h30 e retorno de trem a Cusco.</p>\n\n<h3>Dia 11: Descanso em Cusco</h3>\n<p>Dia livre para relaxar, saborear a gastronomia cusquenha e fazer compras de artesanato andino no bairro de San Blas.</p>\n\n<h3>Dias 12 a 14: Rota do Sol e Lago Titicaca em Puno</h3>\n<p>Viagem cênica em ônibus turístico de primeira classe cruzando os Andes até Puno, com paradas em Andahuaylillas, Raqchi e La Raya. No Dia 13, navegamos pelas ilhas flutuantes de junco dos Uros e pernoitamos com famílias nativas na Ilha Taquile. No Dia 14, visitamos as torres funerárias de Sillustani e voamos de volta a Lima.</p>\n\n<h3>Dia 15: Lima – Voo Internacional de Retorno</h3>\n<p>Café da manhã no hotel e traslado privativo ao aeroporto de Lima para embarque em seu voo de volta ao Brasil com a bagagem cheia de memórias inesquecíveis!</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Voos domésticos inclusos (Lima – Puerto Maldonado – Cusco e Juliaca – Lima)</li>\n	<li>Todos os traslados privativos terrestres e fluviais em todas as cidades</li>\n	<li>2 noites em ecolodge na selva com pensão completa e excursões guiadas</li>\n	<li>Permissão oficial do governo peruano para a Trilha Inca Clássica de 4 dias</li>\n	<li>Equipe completa de trilha: guia oficial de montanha, chef de expedição e carregadores</li>\n	<li>Equipamentos de camping 4 estações e alimentação completa na trilha</li>\n	<li>Ingresso para Machu Picchu, ônibus de descida e trem turístico de retorno</li>\n	<li>Ônibus turístico Rota do Sol com almoço buffet e entradas</li>\n	<li>Excursão náutica de 2 dias no Lago Titicaca com pernoite comunitário em Taquile</li>\n	<li>7 noites em hotéis 3 ou 4 estrelas selecionados com café da manhã</li>\n</ul>', `importante` = '<h3>Orientações importantes:</h3>\n<ul>\n	<li>Exige reserva prévia com 4 a 6 meses de antecedência devido às vagas rígidas da Trilha Inca.</li>\n	<li>Vacina contra febre amarela recomendada para a visita a Tambopata.</li>\n	<li>Passaporte original válido ou RG brasileiro emitido há menos de 10 anos.</li>\n</ul>' WHERE `id` = 27;

UPDATE `tourspt` SET `contenido` = '<h2>Lima, Cidade dos Reis — Tour Gastronômico e Cultural (2 Dias e 1 Noite)</h2>\n<p>A capital peruana, <strong>Lima</strong>, é muito mais do que um ponto de conexão de voos: é a <strong>Capital Gastronômica da América do Sul</strong> e um tesouro histórico tombado como Patrimônio da Humanidade pela UNESCO, onde pirâmides de civilizações pré-incas de dois mil anos convivem harmoniosamente com suntuosas mansões coloniais e os bairros modernos com vista para o Oceano Pacífico.</p>\n\n<p>Este programa de 2 dias e 1 noite foi pensado para proporcionar a melhor introdução à cultura e aos sabores do Peru, seja na sua chegada ao país ou antes de embarcar em seu voo internacional de retorno.</p>', `resumen` = '<h2>Resumo do Roteiro em Lima (2 Dias):</h2>\n<ul>\n	<li><strong>Dia 1:</strong> Recepção no aeroporto – City Tour Colonial e Moderno (Plaza Mayor, Catacumbas de São Francisco e Parque do Amor) – Visita guiada ao Museu Larco – Noite livre em Miraflores</li>\n	<li><strong>Dia 2:</strong> Manhã livre para tour gastronômico de ceviche e compras no Mercado de Surquillo – Traslado ao aeroporto no horário de conexão</li>\n</ul>', `detallado` = '<h2>Roteiro Detalhado:</h2>\n\n<h3>Dia 1: O Melhor de Lima Colonial e os Tesouros Pré-Incas</h3>\n<p>Recepção privativa no Aeroporto Internacional Jorge Chávez e início do nosso tour guiado pela capital. Começamos pelo sítio arqueológico de <strong>Huaca Pucllana</strong> em Miraflores, um imponente centro cerimonial de adobe construído no século V d.C. Seguimos para o Centro Histórico de Lima, admirando a Plaza de Armas, o Palácio de Governo e a imponente Catedral. Visitamos o histórico Convento de São Francisco e suas famosas catacumbas subterrâneas, que abrigaram os primeiros sepultamentos da cidade.</p>\n<p>Ao meio-dia, visitamos o aclamado <strong>Museu Larco</strong>, instalado em uma mansão virreinal do século XVIII cercada por jardins floridos. O museu exibe a mais completa coleção particular de arte pré-colombiana em ouro, prata e cerâmica do mundo, oferecendo uma compreensão profunda das culturas Mochica, Chimú, Nazca e Inca. À tarde, seguimos para o hotel em Miraflores, com passagem pelo Parque do Amor e vista para as falésias do Pacífico.</p>\n\n<h3>Dia 2: Gastronomia Limenha e Despedida do Peru</h3>\n<p>Café da manhã no hotel. Manhã livre para caminhar pelo Malecón de Miraflores, fazer compras de artesanato de alta qualidade no Mercado Inca da Avenida Petit Thouars ou participar de uma experiência gastronômica provando o autêntico ceviche com milho crocante (cancha) e o clássico pisco sour. No horário programado, nosso traslado privativo levará você confortavelmente ao aeroporto para embarque em seu voo internacional.</p>', `incluidos` = '<h3>O que inclui:</h3>\n<ul>\n	<li>Traslados privativos de ida e volta entre o Aeroporto Internacional de Lima e seu hotel em Miraflores</li>\n	<li>1 noite de hospedagem em hotel selecionado com café da manhã</li>\n	<li>City tour completo pela Lima Colonial e Moderna com transporte executivo</li>\n	<li>Guia oficial de turismo credenciado bilíngue especializado na história e gastronomia de Lima</li>\n	<li>Ingressos de entrada para o Museu Larco e para o Convento e Catacumbas de São Francisco</li>\n</ul>', `importante` = '<h3>Dicas:</h3>\n<ul>\n	<li>Ideal para o primeiro ou último dia de viagem pelo Peru.</li>\n	<li>A gastronomia de Lima conta com restaurantes premiados entre os melhores do mundo (Central, Maido, Astrid y Gastón). Recomendamos reservar mesas com bastante antecedência caso deseje jantar nesses estabelecimentos.</li>\n</ul>' WHERE `id` = 28;
